/// Materialize the editor-only type-hint sidecar from an already completed
/// check. Compiler-service diagnostics deliberately defer this global
/// presentation projection; editor clients may request it without parsing or
/// solving the program a second time.
pub fn project_type_hints(program: &ParsedProgram, output: &CheckOutput) -> TypeHintTable {
    if !output.report.type_hint_table.entries.is_empty() {
        return output.report.type_hint_table.clone();
    }

    let (expr_type_table, function_type_table, render_slot_table, source_payload_shape_table) =
        if let Some(checked) = output.program.as_ref() {
            let metadata = &checked.lowering_metadata;
            (
                &metadata.expr_type_table,
                &metadata.function_type_table,
                &metadata.render_slot_table,
                &metadata.source_payload_shape_table,
            )
        } else {
            (
                &output.report.expr_type_table,
                &output.report.function_type_table,
                &output.report.render_slot_table,
                &output.report.source_payload_shape_table,
            )
        };

    let payloads_by_path = source_payload_shape_table
        .iter()
        .map(|entry| (entry.diagnostic_path.as_str(), entry))
        .collect::<BTreeMap<_, _>>();
    let syntax_payloads = syntax_source_sites(program)
        .into_iter()
        .filter_map(|source| {
            let payload = payloads_by_path.get(source.path.as_str())?;
            Some(SourcePayloadSyntaxShapeEntry {
                statement: source.statement,
                source_path: source.path,
                payload_type: payload.payload_type.clone(),
                fields: payload.fields.clone(),
            })
        })
        .collect::<Vec<_>>();
    let source_payload_types = source_payload_shape_table
        .iter()
        .map(|entry| (entry.diagnostic_path.clone(), entry.payload_type.clone()))
        .collect::<BTreeMap<_, _>>();
    let bindings = name_bindings(program, &source_payload_types);
    type_hint_table(
        program,
        expr_type_table,
        function_type_table,
        render_slot_table,
        &syntax_payloads,
        &bindings,
    )
}

fn role_for_namespace(namespace: &str) -> Option<ProgramRole> {
    Some(match boon_syntax::program_role_root(namespace)? {
        boon_syntax::ProgramRoleRoot::Client => ProgramRole::Client,
        boon_syntax::ProgramRoleRoot::Session => ProgramRole::Session,
        boon_syntax::ProgramRoleRoot::Server => ProgramRole::Server,
    })
}

fn external_value_role(parts: &[String]) -> Option<ProgramRole> {
    parts.first().and_then(|part| role_for_namespace(part))
}

fn external_value_path(parts: &[String]) -> Option<String> {
    external_value_role(parts)?;
    (parts.len() > 1).then(|| boon_syntax::canonical_value_path(parts))
}

fn external_value_uses_store_root(parts: &[String]) -> bool {
    parts.len() > 2 && parts.get(1).is_some_and(|part| part == "store")
}

fn external_function_role(function: &str) -> Option<ProgramRole> {
    function
        .split_once('/')
        .and_then(|(namespace, _)| role_for_namespace(namespace))
}

fn role_namespace(role: ProgramRole) -> &'static str {
    role.namespace()
}

fn external_data_type_is_closed(ty: &Type) -> bool {
    match ty {
        Type::Text | Type::Number | Type::Bytes(_) | Type::Bits { .. } => true,
        Type::Object(shape) => {
            !shape.open && shape.fields.values().all(external_data_type_is_closed)
        }
        Type::List(item) => external_data_type_is_closed(item),
        Type::Map { key, value } => {
            external_data_type_is_closed(key) && external_data_type_is_closed(value)
        }
        Type::Set(item) => external_data_type_is_closed(item),
        Type::VariantSet(variants) => variants.iter().all(|variant| match variant {
            Variant::Tag(_) => true,
            Variant::Tagged { fields, .. } => {
                !fields.open && fields.fields.values().all(external_data_type_is_closed)
            }
        }),
        Type::Union(members) => {
            !members.is_empty() && members.iter().all(external_data_type_is_closed)
        }
        Type::Absent
        | Type::RenderContract
        | Type::Function { .. }
        | Type::UnresolvedShape { .. }
        | Type::Var(_)
        | Type::Unknown => false,
    }
}

/// Whether a checked value has the closed, canonical representation required
/// for MAP keys and SET items.
pub fn type_is_map_key_safe(ty: &Type) -> bool {
    match ty {
        Type::Number | Type::Text | Type::Bytes(_) | Type::Bits { .. } => true,
        Type::VariantSet(variants) => {
            !variants.is_empty()
                && variants.iter().all(|variant| match variant {
                    Variant::Tag(_) => true,
                    Variant::Tagged { fields, .. } => {
                        !fields.open && fields.fields.values().all(type_is_map_key_safe)
                    }
                })
        }
        Type::Object(shape) => !shape.open && shape.fields.values().all(type_is_map_key_safe),
        Type::Absent
        | Type::RenderContract
        | Type::List(_)
        | Type::Function { .. }
        | Type::UnresolvedShape { .. }
        | Type::Var(_)
        | Type::Unknown
        | Type::Union(_)
        | Type::Map { .. }
        | Type::Set(_) => false,
    }
}

fn type_may_contain_collection_authority(ty: &Type) -> bool {
    match ty {
        Type::List(_) | Type::Map { .. } | Type::Set(_) => true,
        Type::Object(shape) => shape
            .fields
            .values()
            .any(type_may_contain_collection_authority),
        Type::VariantSet(variants) => variants.iter().any(|variant| match variant {
            Variant::Tag(_) => false,
            Variant::Tagged { fields, .. } => fields
                .fields
                .values()
                .any(type_may_contain_collection_authority),
        }),
        Type::Union(members) => members.iter().any(type_may_contain_collection_authority),
        Type::Function { .. } | Type::UnresolvedShape { .. } | Type::Var(_) | Type::Unknown => {
            false
        }
        Type::Text
        | Type::Number
        | Type::Bytes(_)
        | Type::Bits { .. }
        | Type::Absent
        | Type::RenderContract => false,
    }
}

fn external_type_environment_diagnostics(
    environment: &ExternalTypeEnvironment,
) -> Vec<TypeDiagnostic> {
    let mut diagnostics = Vec::new();
    for (path, flow_type) in &environment.values {
        let valid_path = path.split_once('/').is_some_and(|(namespace, suffix)| {
            role_for_namespace(namespace).is_some()
                && !suffix.is_empty()
                && !suffix.split('.').any(str::is_empty)
        });
        if !valid_path {
            diagnostics.push(diagnostic_at_line(
                1,
                format!(
                    "external value `{path}` must use an exact qualified path such as `Server/store.count`"
                ),
            ));
        }
        if flow_type.mode == FlowMode::Absent {
            diagnostics.push(diagnostic_at_line(
                1,
                format!("external value `{path}` cannot be always absent"),
            ));
        }
        if !environment.allow_unresolved && !external_data_type_is_closed(&flow_type.ty) {
            diagnostics.push(diagnostic_at_line(
                1,
                format!(
                    "external value `{path}` must have a closed value type; found {}",
                    boon_facing_type_label(&flow_type.ty)
                ),
            ));
        }
    }
    for (function, signature) in &environment.functions {
        let valid_function = function.split_once('/').is_some_and(|(namespace, suffix)| {
            role_for_namespace(namespace).is_some()
                && !suffix.is_empty()
                && !suffix.split('/').any(str::is_empty)
        });
        if !valid_function {
            diagnostics.push(diagnostic_at_line(
                1,
                format!(
                    "external function `{function}` must use an exact qualified name such as `Server/Module/format`"
                ),
            ));
        }
        if !environment.allow_unresolved && !external_data_type_is_closed(&signature.result.ty) {
            diagnostics.push(diagnostic_at_line(
                1,
                format!(
                    "external function `{function}` must have a closed result type; found {}",
                    boon_facing_type_label(&signature.result.ty)
                ),
            ));
        }
        let mut names = BTreeSet::new();
        for arg in &signature.args {
            if arg.name.is_empty() || !names.insert(arg.name.as_str()) {
                diagnostics.push(diagnostic_at_line(
                    1,
                    format!(
                        "external function `{function}` has an empty or duplicate argument name `{}`",
                        arg.name
                    ),
                ));
            }
            if !environment.allow_unresolved && !external_data_type_is_closed(&arg.flow_type.ty) {
                diagnostics.push(diagnostic_at_line(
                    1,
                    format!(
                        "external function `{function}` argument `{}` must have a closed value type; found {}",
                        arg.name,
                        boon_facing_type_label(&arg.flow_type.ty)
                    ),
                ));
            }
        }
    }

    let mut claimed_declarations =
        BTreeMap::<(ProgramRole, SourceBundleDigestV1, DeclId), &str>::new();
    for (name, identity) in &environment.external_identities {
        let expected = if environment.values.contains_key(name) {
            Some(CheckedExternalDeclarationKind::Value)
        } else if environment.functions.contains_key(name) {
            Some(CheckedExternalDeclarationKind::Callable)
        } else {
            None
        };
        let Some(expected) = expected else {
            diagnostics.push(diagnostic_at_line(
                1,
                format!(
                    "external declaration identity `{name}` has no matching external value or function"
                ),
            ));
            continue;
        };
        if identity.kind != expected {
            diagnostics.push(diagnostic_at_line(
                1,
                format!(
                    "external declaration identity `{name}` has kind {:?}, expected {expected:?}",
                    identity.kind
                ),
            ));
        }
        let named_role = name
            .split_once('/')
            .and_then(|(namespace, _)| role_for_namespace(namespace));
        if named_role != Some(identity.producer_role) {
            diagnostics.push(diagnostic_at_line(
                1,
                format!(
                    "external declaration identity `{name}` targets {:?}, which does not match its qualified role",
                    identity.producer_role
                ),
            ));
        }
        if identity.producer_role == environment.current_role
            || !environment
                .current_role
                .can_depend_on(identity.producer_role)
        {
            diagnostics.push(diagnostic_at_line(
                1,
                format!(
                    "external declaration identity `{name}` targets a role that {} cannot depend on",
                    environment.current_role.namespace()
                ),
            ));
        }
        if identity
            .producer_source_bundle_digest_v1
            .as_bytes()
            .iter()
            .all(|byte| *byte == 0)
            || identity.producer_declaration == DeclId(0)
        {
            diagnostics.push(diagnostic_at_line(
                1,
                format!(
                    "external declaration identity `{name}` has a zero producer source or declaration identity"
                ),
            ));
        }
        let declaration_key = (
            identity.producer_role,
            identity.producer_source_bundle_digest_v1,
            identity.producer_declaration,
        );
        if let Some(previous) = claimed_declarations.insert(declaration_key, name) {
            diagnostics.push(diagnostic_at_line(
                1,
                format!(
                    "external declarations `{previous}` and `{name}` select the same producer declaration"
                ),
            ));
        }
    }
    if environment.require_resolved_identities {
        for name in environment
            .values
            .keys()
            .chain(environment.functions.keys())
        {
            if !environment.external_identities.contains_key(name) {
                diagnostics.push(diagnostic_at_line(
                    1,
                    format!(
                        "sealed external declaration `{name}` is missing its source-bound producer identity"
                    ),
                ));
            }
        }
    }
    diagnostics
}

/// Deterministic, timer-free work performed by one complete typecheck request.
///
/// These counters are incremented at the owning worklist, cache, or diagnostic
/// lookup. They deliberately do not infer work from the size of the resulting
/// checked program or report. Consequently they can be compared across runs
/// and used by scaling gates without depending on wall-clock noise.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq, Serialize, Deserialize)]
#[serde(default)]
pub struct TypeCheckWorkCounters {
    pub inference_invocations: u64,
    pub inference_rounds: u64,
    pub inference_expression_visits: u64,
    pub inference_declaration_visits: u64,
    pub inference_callable_visits: u64,
    pub inference_call_visits: u64,
    pub inference_call_changed_visits: u64,
    pub inference_call_noop_visits: u64,
    pub inference_call_seed_enqueues: u64,
    pub inference_call_input_enqueues: u64,
    pub inference_call_output_enqueues: u64,
    pub inference_call_callee_enqueues: u64,
    pub inference_call_selector_enqueues: u64,
    pub inference_call_output_scope_enqueues: u64,
    pub inference_call_output_origin_skips: u64,
    pub inference_selector_visits: u64,
    pub inference_pattern_visits: u64,
    pub context_scheme_worklist_invocations: u64,
    pub context_scheme_worklist_visits: u64,
    pub context_scheme_worklist_changes: u64,
    pub wrapper_scheme_worklist_invocations: u64,
    pub wrapper_scheme_worklist_visits: u64,
    pub wrapper_scheme_changed_owners: u64,
    pub wrapper_scheme_parameter_changes: u64,
    pub wrapper_scheme_result_changes: u64,
    pub checked_flow_cache_hits: u64,
    pub checked_flow_cache_misses: u64,
    pub checked_flow_cache_invalidations: u64,
    pub checked_flow_cache_reverse_invalidation_traversals: u64,
    pub checked_flow_cache_full_resets: u64,
    pub checked_flow_cache_rejected_invalid_ids: u64,
    pub checked_flow_indexed_read_hits: u64,
    pub checked_flow_indexed_read_missing: u64,
    pub checked_flow_indexed_read_rejected: u64,
    pub checked_flow_indexed_out_hits: u64,
    pub checked_flow_indexed_out_missing: u64,
    /// Checked expressions considered while installing the diagnostic lookup.
    /// This is an attempt counter: duplicate and out-of-range IDs remain
    /// classified separately below and are not silently subtracted.
    pub diagnostic_flow_install_attempts: u64,
    pub diagnostic_flow_duplicate_ids: u64,
    pub diagnostic_flow_out_of_range_ids: u64,
    pub diagnostic_flow_missing_parser_ids: u64,
    /// Every diagnostic `ensure_expr` lookup after checked replay is enabled.
    /// Repeated requests for one expression are counted repeatedly.
    pub diagnostic_replay_requests: u64,
    pub diagnostic_replay_hits: u64,
    pub diagnostic_replay_misses: u64,
    /// Distinct expression IDs whose checked diagnostics were replayed.
    pub diagnostic_replay_unique_expressions: u64,
}

impl TypeCheckWorkCounters {
    /// Every inference call visit is classified exactly once as changed or a
    /// no-op. A false result identifies instrumentation drift or saturation.
    #[must_use]
    pub fn inference_call_visits_are_fully_classified(&self) -> bool {
        self.inference_call_changed_visits
            .checked_add(self.inference_call_noop_visits)
            == Some(self.inference_call_visits)
    }

    /// A replay request increments before lookup and then takes exactly one
    /// hit or miss branch. Unique-expression replay is intentionally separate
    /// because multiple diagnostics may request the same expression.
    #[must_use]
    pub fn diagnostic_replay_is_fully_accounted(&self) -> bool {
        self.diagnostic_replay_hits
            .checked_add(self.diagnostic_replay_misses)
            == Some(self.diagnostic_replay_requests)
    }

    fn add_usize(counter: &mut u64, value: usize) {
        *counter = counter.saturating_add(value as u64);
    }

    fn record_inference(&mut self, stats: &CheckedTypeInferenceWorkStats) {
        self.inference_invocations = self.inference_invocations.saturating_add(1);
        Self::add_usize(&mut self.inference_rounds, stats.rounds);
        Self::add_usize(
            &mut self.inference_expression_visits,
            stats.expression_visits,
        );
        Self::add_usize(
            &mut self.inference_declaration_visits,
            stats.declaration_visits,
        );
        Self::add_usize(&mut self.inference_callable_visits, stats.callable_visits);
        Self::add_usize(&mut self.inference_call_visits, stats.call_visits);
        Self::add_usize(
            &mut self.inference_call_changed_visits,
            stats.call_changed_visits,
        );
        Self::add_usize(&mut self.inference_call_noop_visits, stats.call_noop_visits);
        Self::add_usize(
            &mut self.inference_call_seed_enqueues,
            stats.call_seed_enqueues,
        );
        Self::add_usize(
            &mut self.inference_call_input_enqueues,
            stats.call_input_enqueues,
        );
        Self::add_usize(
            &mut self.inference_call_output_enqueues,
            stats.call_output_enqueues,
        );
        Self::add_usize(
            &mut self.inference_call_callee_enqueues,
            stats.call_callee_enqueues,
        );
        Self::add_usize(
            &mut self.inference_call_selector_enqueues,
            stats.call_selector_enqueues,
        );
        Self::add_usize(
            &mut self.inference_call_output_scope_enqueues,
            stats.call_output_scope_enqueues,
        );
        Self::add_usize(
            &mut self.inference_call_output_origin_skips,
            stats.call_output_origin_skips,
        );
        Self::add_usize(&mut self.inference_selector_visits, stats.selector_visits);
        Self::add_usize(&mut self.inference_pattern_visits, stats.pattern_visits);
    }

    fn record_context_scheme_worklist(&mut self, visits: usize, changes: usize) {
        self.context_scheme_worklist_invocations =
            self.context_scheme_worklist_invocations.saturating_add(1);
        Self::add_usize(&mut self.context_scheme_worklist_visits, visits);
        Self::add_usize(&mut self.context_scheme_worklist_changes, changes);
    }

    fn record_wrapper_scheme_worklist(
        &mut self,
        visits: usize,
        changed_owners: usize,
        parameter_changes: usize,
        result_changes: usize,
    ) {
        self.wrapper_scheme_worklist_invocations =
            self.wrapper_scheme_worklist_invocations.saturating_add(1);
        Self::add_usize(&mut self.wrapper_scheme_worklist_visits, visits);
        Self::add_usize(&mut self.wrapper_scheme_changed_owners, changed_owners);
        Self::add_usize(
            &mut self.wrapper_scheme_parameter_changes,
            parameter_changes,
        );
        Self::add_usize(&mut self.wrapper_scheme_result_changes, result_changes);
    }

    fn record_flow_cache(&mut self, stats: CheckedFlowInferenceCacheStats) {
        self.checked_flow_cache_hits = stats.hits;
        self.checked_flow_cache_misses = stats.misses;
        self.checked_flow_cache_invalidations = stats.invalidations;
        self.checked_flow_cache_reverse_invalidation_traversals =
            stats.reverse_invalidation_traversals;
        self.checked_flow_cache_full_resets = stats.full_resets;
        self.checked_flow_cache_rejected_invalid_ids = stats.rejected_invalid_ids;
        self.checked_flow_indexed_read_hits = stats.indexed_read_hits;
        self.checked_flow_indexed_read_missing = stats.indexed_read_missing;
        self.checked_flow_indexed_read_rejected = stats.indexed_read_rejected;
        self.checked_flow_indexed_out_hits = stats.indexed_out_hits;
        self.checked_flow_indexed_out_missing = stats.indexed_out_missing;
    }

    fn record_diagnostic_replay(
        &mut self,
        install_attempts: usize,
        duplicate_ids: usize,
        out_of_range_ids: usize,
        missing_parser_ids: usize,
        requests: usize,
        hits: usize,
        misses: usize,
        unique_expressions: usize,
    ) {
        self.diagnostic_flow_install_attempts = install_attempts as u64;
        self.diagnostic_flow_duplicate_ids = duplicate_ids as u64;
        self.diagnostic_flow_out_of_range_ids = out_of_range_ids as u64;
        self.diagnostic_flow_missing_parser_ids = missing_parser_ids as u64;
        self.diagnostic_replay_requests = requests as u64;
        self.diagnostic_replay_hits = hits as u64;
        self.diagnostic_replay_misses = misses as u64;
        self.diagnostic_replay_unique_expressions = unique_expressions as u64;
    }
}

