fn name_bindings(
    program: &ParsedProgram,
    source_payload_types: &BTreeMap<String, Type>,
) -> BTreeMap<String, Type> {
    let mut bindings = BTreeMap::new();
    collect_name_bindings(
        &program.ast.statements,
        &program.expressions,
        &mut Vec::new(),
        source_payload_types,
        &mut bindings,
    );
    collect_state_cell_path_bindings(program, &mut bindings);
    bindings
}

fn collect_state_cell_path_bindings(
    program: &ParsedProgram,
    bindings: &mut BTreeMap<String, Type>,
) {
    for item in &program.ast.items {
        let (Some(field), Some(hold_name)) = (item.field.as_ref(), item.hold.as_ref()) else {
            continue;
        };
        let ty = bindings
            .get(hold_name.as_str())
            .cloned()
            .unwrap_or_else(open_object_type);
        bindings.entry(field.clone()).or_insert(ty);
    }
}

fn static_expr_type_from_bindings(
    expr: &AstExpr,
    expressions: &[AstExpr],
    bindings: &dyn StaticBindingLookup,
) -> Option<Type> {
    if let Some(ty) = static_bits_result_type_from_bindings(expr, expressions, bindings) {
        return Some(ty);
    }
    if let AstExprKind::Call { function, .. } | AstExprKind::Pipe { op: function, .. } = &expr.kind
        && let Some(signature) = host_effect_signature(function)
    {
        return Some(signature.result_type);
    }
    match &expr.kind {
        AstExprKind::Object(fields) => Some(Type::object(ObjectShape::from_ordered_fields(
            fields.iter().filter(|field| !field.spread).map(|field| {
                (
                    field.name.clone(),
                    expressions
                        .get(field.value)
                        .and_then(|field_expr| {
                            static_expr_type_from_bindings(field_expr, expressions, bindings)
                        })
                        .unwrap_or_else(open_object_type),
                )
            }),
            false,
        ))),
        AstExprKind::Identifier(name) => bindings.static_binding(name).cloned(),
        AstExprKind::Path(parts) => static_path_type_from_bindings(parts, bindings),
        AstExprKind::Drain { path } => {
            static_path_type_from_bindings(&drain_path_parts(path), bindings)
        }
        AstExprKind::Draining { input } => expressions
            .get(*input)
            .and_then(|expr| static_expr_type_from_bindings(expr, expressions, bindings)),
        AstExprKind::Then { input, output } => output
            .or(Some(*input))
            .and_then(|expr_id| expressions.get(expr_id))
            .and_then(|expr| static_expr_type_from_bindings(expr, expressions, bindings)),
        AstExprKind::MatchArm {
            output: Some(output),
            ..
        } => expressions
            .get(*output)
            .and_then(|expr| static_expr_type_from_bindings(expr, expressions, bindings)),
        AstExprKind::MatchArm { output: None, .. } => Some(Type::Absent),
        AstExprKind::When { .. } => static_when_type_from_bindings(expr.id, expressions, bindings),
        AstExprKind::Pipe { op, .. } if op == "WHILE" => {
            static_when_type_from_bindings(expr.id, expressions, bindings)
        }
        AstExprKind::StringLiteral(_) | AstExprKind::TextLiteral(_) => Some(Type::Text),
        AstExprKind::Number(_) => Some(Type::Number),
        AstExprKind::BitsLiteral { width, .. } => Some(Type::Bits { width: *width }),
        AstExprKind::ByteLiteral { .. } => Some(Type::Bytes(BytesType::Fixed(1))),
        AstExprKind::BytesLiteral { size, items } => Some(static_bytes_literal_type(
            size,
            items,
            expressions,
            |expr| static_expr_type_from_bindings(expr, expressions, bindings),
        )),
        AstExprKind::Tag(tag) if tag == "SKIP" => Some(Type::Absent),
        AstExprKind::Tag(tag) => Some(Type::VariantSet(vec![Variant::Tag(tag.clone())].into())),
        AstExprKind::Call { .. } | AstExprKind::Pipe { .. } => {
            let ty = simple_expr_type(expr, expressions);
            is_specific_type(&ty).then_some(ty)
        }
        _ => None,
    }
}

fn resolved_bits_builtin_result(
    function: &str,
    bits_type: Option<Type>,
    named_type: &dyn Fn(&str) -> Option<Type>,
    width_arg: &dyn Fn(&str) -> Option<u32>,
) -> Option<Type> {
    let bits_width = match &bits_type {
        Some(Type::Bits { width }) => Some(*width),
        _ => None,
    };
    let named_bits_width = |name: &str| match named_type(name) {
        Some(Type::Bits { width }) => Some(width),
        _ => None,
    };
    match function {
        "Bits/width" | "Bits/to_number" => Some(Type::Number),
        "Bits/get" => Some(true_false_type()),
        "Bits/compare" => Some(bits_comparison_type()),
        "Bits/set"
        | "Bits/set_slice"
        | "Bits/and"
        | "Bits/or"
        | "Bits/xor"
        | "Bits/not"
        | "Bits/shift_left"
        | "Bits/shift_right"
        | "Bits/shift_right_arithmetic"
        | "Bits/rotate_left"
        | "Bits/rotate_right"
        | "Bits/add_or_wrap"
        | "Bits/subtract_or_wrap" => bits_type,
        "Bits/slice" => width_arg("count").map(|width| Type::Bits { width }),
        "Bits/concat" => bits_width
            .zip(named_bits_width("with"))
            .and_then(|(left, right)| left.checked_add(right))
            .filter(|width| *width <= MAX_BITS_WIDTH)
            .map(|width| Type::Bits { width }),
        "Bits/zero_extend" | "Bits/sign_extend" | "Bits/truncate" | "Bytes/to_bits" => {
            width_arg("width").map(|width| Type::Bits { width })
        }
        "Bits/add_widening" => bits_width
            .and_then(|width| width.checked_add(1))
            .filter(|width| *width <= MAX_BITS_WIDTH)
            .map(|width| Type::Bits { width }),
        "Bits/try_add" => bits_type.map(bits_added_type),
        "Bits/try_subtract" => bits_type.map(bits_subtracted_type),
        "Number/to_bits" => {
            width_arg("width").map(|width| bits_converted_type(Type::Bits { width }))
        }
        "Bits/to_bytes" => bits_width.map(|width| {
            Type::Bytes(BytesType::Fixed(
                usize::try_from(width / 8).unwrap_or(usize::MAX),
            ))
        }),
        _ => None,
    }
}

fn static_bits_result_type_from_bindings(
    expr: &AstExpr,
    expressions: &[AstExpr],
    bindings: &dyn StaticBindingLookup,
) -> Option<Type> {
    let (function, piped_input, args) = match &expr.kind {
        AstExprKind::Call { function, args, .. } => (function.as_str(), None, args.as_slice()),
        AstExprKind::Pipe {
            input, op, args, ..
        } => (
            op.as_str(),
            Some(expr.linked_input.unwrap_or(*input)),
            args.as_slice(),
        ),
        _ => return None,
    };
    if !is_bits_builtin(function) {
        return None;
    }

    fn static_width(expressions: &[AstExpr], expr_id: usize) -> Option<u32> {
        fn evaluate(
            expressions: &[AstExpr],
            expr_id: usize,
            active: &mut BTreeSet<usize>,
        ) -> Option<ExactNumber> {
            if !active.insert(expr_id) {
                return None;
            }
            let result = match &expressions.get(expr_id)?.kind {
                AstExprKind::Number(value) => ExactNumber::parse_strict(value, None).ok(),
                AstExprKind::Infix { left, op, right } => {
                    let left = evaluate(expressions, *left, active)?;
                    let right = evaluate(expressions, *right, active)?;
                    match op.as_str() {
                        "+" => left.checked_add(&right).ok(),
                        "-" => left.checked_sub(&right).ok(),
                        "*" => left.checked_mul(&right).ok(),
                        "/" => left.checked_div(&right).ok(),
                        "%" => left.checked_rem(&right).ok(),
                        _ => None,
                    }
                }
                _ => None,
            };
            active.remove(&expr_id);
            result
        }

        evaluate(expressions, expr_id, &mut BTreeSet::new())
            .and_then(|value| value.to_u64_exact().ok())
            .and_then(|value| u32::try_from(value).ok())
            .filter(|width| (1..=MAX_BITS_WIDTH).contains(width))
    }

    let type_for_expr = |expr_id| {
        expressions
            .get(expr_id)
            .and_then(|expr| static_expr_type_from_bindings(expr, expressions, bindings))
    };
    let bits_type = piped_input
        .or_else(|| named_arg_expr(args, "bits"))
        .and_then(type_for_expr);
    let named_bits_type = |name: &str| named_arg_expr(args, name).and_then(type_for_expr);
    let width_arg =
        |name: &str| named_arg_expr(args, name).and_then(|expr| static_width(expressions, expr));
    resolved_bits_builtin_result(function, bits_type, &named_bits_type, &width_arg)
}

fn static_path_type_from_bindings(
    parts: &[String],
    bindings: &dyn StaticBindingLookup,
) -> Option<Type> {
    type_from_longest_binding_prefix(bindings, parts)
}

fn refresh_external_declaration_bindings(
    statements: &[AstStatement],
    expressions: &[AstExpr],
    external_types: &ExternalTypeEnvironment,
    scope: &mut Vec<String>,
    bindings: &mut BTreeMap<String, Type>,
) {
    for statement in statements {
        match &statement.kind {
            AstStatementKind::Function { .. } => continue,
            AstStatementKind::Field { name } => {
                let path = scoped_path(scope, name);
                if let Some(expr_id) = direct_statement_value_expr_id(statement, expressions)
                    .map(|expr_id| expression_result_expr_id(expr_id, expressions))
                    && let Some(expr) = expressions.get(expr_id)
                    && let Some(ty) = static_expr_type_with_external_types(
                        expr,
                        expressions,
                        bindings,
                        external_types,
                    )
                {
                    insert_simple_binding_preserving_renderable(bindings, name, ty.clone());
                    bindings.insert(path.clone(), ty);
                }
                scope.push(name.clone());
                refresh_external_declaration_bindings(
                    &statement.children,
                    expressions,
                    external_types,
                    scope,
                    bindings,
                );
                scope.pop();
            }
            _ => refresh_external_declaration_bindings(
                &statement.children,
                expressions,
                external_types,
                scope,
                bindings,
            ),
        }
    }
}

fn static_expr_type_with_external_types(
    expr: &AstExpr,
    expressions: &[AstExpr],
    bindings: &dyn StaticBindingLookup,
    external_types: &ExternalTypeEnvironment,
) -> Option<Type> {
    match &expr.kind {
        AstExprKind::Call { function, .. } | AstExprKind::Pipe { op: function, .. }
            if external_function_role(function).is_some() =>
        {
            external_types
                .functions
                .get(function)
                .map(|signature| signature.result.ty.clone())
        }
        AstExprKind::Object(fields) => Some(Type::object(ObjectShape::from_ordered_fields(
            fields.iter().filter(|field| !field.spread).map(|field| {
                (
                    field.name.clone(),
                    expressions
                        .get(field.value)
                        .and_then(|field_expr| {
                            static_expr_type_with_external_types(
                                field_expr,
                                expressions,
                                bindings,
                                external_types,
                            )
                        })
                        .unwrap_or_else(open_object_type),
                )
            }),
            false,
        ))),
        AstExprKind::TaggedObject { tag, fields } => Some(Type::VariantSet(
            vec![Variant::Tagged {
                tag: tag.clone(),
                fields: ObjectShape::from_ordered_fields(
                    fields.iter().filter(|field| !field.spread).map(|field| {
                        (
                            field.name.clone(),
                            expressions
                                .get(field.value)
                                .and_then(|field_expr| {
                                    static_expr_type_with_external_types(
                                        field_expr,
                                        expressions,
                                        bindings,
                                        external_types,
                                    )
                                })
                                .unwrap_or_else(open_object_type),
                        )
                    }),
                    false,
                ),
            }]
            .into(),
        )),
        AstExprKind::Draining { input } => expressions.get(*input).and_then(|input| {
            static_expr_type_with_external_types(input, expressions, bindings, external_types)
        }),
        AstExprKind::Then { input, output } => output
            .or(Some(*input))
            .and_then(|expr_id| expressions.get(expr_id))
            .and_then(|output| {
                static_expr_type_with_external_types(output, expressions, bindings, external_types)
            }),
        AstExprKind::MatchArm {
            output: Some(output),
            ..
        } => expressions.get(*output).and_then(|output| {
            static_expr_type_with_external_types(output, expressions, bindings, external_types)
        }),
        _ => static_expr_type_from_bindings(expr, expressions, bindings),
    }
}

fn flow_bindings(
    program: &ParsedProgram,
    external_types: &ExternalTypeEnvironment,
) -> FlowModeIndex {
    let mut bindings = FlowModeIndex::default();
    for (path, flow_type) in &external_types.values {
        bindings.insert(path.clone(), flow_type.mode);
    }
    collect_flow_bindings(
        &program.ast.statements,
        &program.expressions,
        &mut Vec::new(),
        &mut bindings,
    );
    bindings
}

fn collect_canonical_named_value_sites(
    statements: &[AstStatement],
    scope: &mut Vec<String>,
    sites: &mut BTreeMap<String, Vec<usize>>,
) {
    for statement in statements {
        match &statement.kind {
            AstStatementKind::Function { .. } => {}
            AstStatementKind::Field { name } if matches!(name.as_str(), "document" | "scene") => {}
            AstStatementKind::Field { name } => {
                let path = scoped_path(scope, name);
                sites.entry(path).or_default().push(statement.id);
                scope.push(name.clone());
                collect_canonical_named_value_sites(&statement.children, scope, sites);
                scope.pop();
            }
            AstStatementKind::Hold { field, name, .. } => {
                if let Some(name) = field.as_ref().or(name.as_ref()) {
                    let path = if scope.last() == Some(name) {
                        scope.join(".")
                    } else {
                        scoped_path(scope, name)
                    };
                    sites.entry(path).or_default().push(statement.id);
                }
            }
            AstStatementKind::List {
                field: Some(name), ..
            }
            | AstStatementKind::Source {
                field: Some(name), ..
            } => {
                sites
                    .entry(scoped_path(scope, name))
                    .or_default()
                    .push(statement.id);
            }
            AstStatementKind::Block => {
                collect_canonical_named_value_sites(&statement.children, scope, sites);
            }
            AstStatementKind::List { field: None, .. }
            | AstStatementKind::Source { field: None, .. }
            | AstStatementKind::Spread
            | AstStatementKind::Expression => {}
        }
    }
    for statement_ids in sites.values_mut() {
        statement_ids.sort_unstable();
        statement_ids.dedup();
    }
}

fn declaration_expression_index(program: &ParsedProgram) -> DeclarationExprIndex {
    let mut declarations = BTreeMap::new();
    collect_declaration_expressions(
        &program.ast.statements,
        &program.expressions,
        &mut Vec::new(),
        &mut declarations,
    );
    DeclarationExprIndex::from_exact(declarations)
}

fn collect_declaration_expressions(
    statements: &[AstStatement],
    expressions: &[AstExpr],
    scope: &mut Vec<String>,
    declarations: &mut BTreeMap<String, usize>,
) {
    for statement in statements {
        match &statement.kind {
            AstStatementKind::Function { .. } => continue,
            AstStatementKind::Field { name } if matches!(name.as_str(), "document" | "scene") => {
                continue;
            }
            AstStatementKind::Field { name } => {
                let path = scoped_path(scope, name);
                if let Some(expr_id) =
                    canonical_statement_value_expression(statements, statement, expressions)
                {
                    declarations.insert(path, expr_id);
                }
                scope.push(name.clone());
                collect_declaration_expressions(
                    &statement.children,
                    expressions,
                    scope,
                    declarations,
                );
                scope.pop();
                continue;
            }
            AstStatementKind::Hold { field, name, .. } => {
                if let Some(name) = field.as_ref().or(name.as_ref())
                    && let Some(expr_id) =
                        canonical_statement_value_expression(statements, statement, expressions)
                {
                    let path = if scope.last() == Some(name) {
                        scope.join(".")
                    } else {
                        scoped_path(scope, name)
                    };
                    declarations.insert(path, expr_id);
                }
            }
            AstStatementKind::List {
                field: Some(name), ..
            }
            | AstStatementKind::Source {
                field: Some(name), ..
            } => {
                if let Some(expr_id) =
                    canonical_statement_value_expression(statements, statement, expressions)
                {
                    declarations.insert(scoped_path(scope, name), expr_id);
                }
            }
            AstStatementKind::Block
            | AstStatementKind::List { field: None, .. }
            | AstStatementKind::Source { field: None, .. }
            | AstStatementKind::Spread
            | AstStatementKind::Expression => {}
        }
        collect_declaration_expressions(&statement.children, expressions, scope, declarations);
    }
}

fn declaration_expr_for_path(declarations: &DeclarationExprIndex, path: &str) -> Option<usize> {
    declarations.resolve(path)
}

fn collect_inferred_named_value_types(
    statements: &[AstStatement],
    expressions: &[AstExpr],
    expr_type_cache: &[Option<FlowType>],
    scope: &mut Vec<String>,
    types: &mut BTreeMap<String, Type>,
) {
    for statement in statements {
        match &statement.kind {
            AstStatementKind::Function { .. } => continue,
            AstStatementKind::Field { name } if matches!(name.as_str(), "document" | "scene") => {
                continue;
            }
            AstStatementKind::Field { name } => {
                let path = scoped_path(scope, name);
                if let Some(ty) = inferred_statement_type(statement, expressions, expr_type_cache) {
                    types.insert(path, ty);
                }
                scope.push(name.clone());
                collect_inferred_named_value_types(
                    &statement.children,
                    expressions,
                    expr_type_cache,
                    scope,
                    types,
                );
                scope.pop();
                continue;
            }
            AstStatementKind::Hold { field, name, .. } => {
                if let Some(name) = field.as_ref().or(name.as_ref())
                    && let Some(ty) =
                        inferred_statement_type(statement, expressions, expr_type_cache)
                {
                    let path = if scope.last() == Some(name) {
                        scope.join(".")
                    } else {
                        scoped_path(scope, name)
                    };
                    types.insert(path, ty);
                }
            }
            AstStatementKind::List {
                field: Some(name), ..
            }
            | AstStatementKind::Source {
                field: Some(name), ..
            } => {
                if let Some(ty) = inferred_statement_type(statement, expressions, expr_type_cache) {
                    types.insert(scoped_path(scope, name), ty);
                }
            }
            AstStatementKind::Block
            | AstStatementKind::List { field: None, .. }
            | AstStatementKind::Source { field: None, .. }
            | AstStatementKind::Spread
            | AstStatementKind::Expression => {}
        }
        collect_inferred_named_value_types(
            &statement.children,
            expressions,
            expr_type_cache,
            scope,
            types,
        );
    }
}

fn inferred_statement_type(
    statement: &AstStatement,
    expressions: &[AstExpr],
    expr_type_cache: &[Option<FlowType>],
) -> Option<Type> {
    statement_pipeline_final_expr_id(statement, expressions)
        .or_else(|| direct_statement_value_expr_id(statement, expressions))
        .and_then(|expr_id| expr_type_cache.get(expr_id))
        .and_then(Option::as_ref)
        .map(|flow| flow.ty.clone())
}

fn collect_flow_bindings(
    statements: &[AstStatement],
    expressions: &[AstExpr],
    scope: &mut Vec<String>,
    bindings: &mut FlowModeIndex,
) {
    for statement in statements {
        match &statement.kind {
            AstStatementKind::Field { name } if name == "document" => continue,
            AstStatementKind::Field { name } => {
                if let Some(expr_id) = direct_statement_value_expr_id(statement, expressions)
                    && let Some(expr) = expressions.get(expr_id)
                {
                    let mode = simple_statement_flow_mode(statement, expr, expressions, bindings);
                    insert_flow_binding(bindings, name.clone(), mode);
                    insert_flow_binding(bindings, scoped_path(scope, name), mode);
                }
                scope.push(name.clone());
                collect_flow_bindings(&statement.children, expressions, scope, bindings);
                scope.pop();
            }
            AstStatementKind::Hold {
                name: Some(name), ..
            } => {
                let path = if scope.last() == Some(name) {
                    scope.join(".")
                } else {
                    scoped_path(scope, name)
                };
                insert_flow_binding(bindings, name.clone(), FlowMode::Continuous);
                insert_flow_binding(bindings, path, FlowMode::Continuous);
                collect_flow_bindings(&statement.children, expressions, scope, bindings);
            }
            AstStatementKind::Source {
                field: Some(name), ..
            } => {
                insert_flow_binding(bindings, name.clone(), FlowMode::PresentOrAbsent);
                insert_flow_binding(
                    bindings,
                    scoped_path(scope, name),
                    FlowMode::PresentOrAbsent,
                );
                collect_flow_bindings(&statement.children, expressions, scope, bindings);
            }
            _ => collect_flow_bindings(&statement.children, expressions, scope, bindings),
        }
    }
}

fn insert_flow_binding(bindings: &mut FlowModeIndex, path: String, mode: FlowMode) {
    bindings.insert(path, mode);
}

fn flow_binding_mode(bindings: &FlowModeIndex, path: &str) -> Option<FlowMode> {
    bindings.resolve(path)
}

fn simple_statement_flow_mode(
    statement: &AstStatement,
    expr: &AstExpr,
    expressions: &[AstExpr],
    bindings: &FlowModeIndex,
) -> FlowMode {
    let AstExprKind::Latest { branches } = &expr.kind else {
        return simple_flow_mode_with_bindings(expr, expressions, bindings);
    };
    let branch_mode = latest_flow_mode(
        branches
            .iter()
            .filter_map(|branch| expressions.get(*branch))
            .map(|branch| simple_flow_mode_with_bindings(branch, expressions, bindings)),
    );
    branch_mode.unwrap_or_else(|| {
        latest_flow_mode(statement.children.iter().filter_map(|child| {
            direct_statement_value_expr_id(child, expressions)
                .and_then(|expr_id| expressions.get(expr_id))
                .map(|expr| simple_statement_flow_mode(child, expr, expressions, bindings))
        }))
        .unwrap_or(FlowMode::Continuous)
    })
}

fn simple_flow_mode_with_bindings(
    expr: &AstExpr,
    expressions: &[AstExpr],
    bindings: &FlowModeIndex,
) -> FlowMode {
    match &expr.kind {
        AstExprKind::Identifier(path) => {
            flow_binding_mode(bindings, path).unwrap_or(FlowMode::Continuous)
        }
        AstExprKind::Path(parts) => {
            let path = external_value_path(parts).unwrap_or_else(|| parts.join("."));
            flow_binding_mode(bindings, &path).unwrap_or(FlowMode::Continuous)
        }
        AstExprKind::Call { function, .. }
            if matches!(function.as_str(), "Stream/pulses" | "Stream/skip") =>
        {
            FlowMode::PresentOrAbsent
        }
        AstExprKind::Call { args, .. } => args
            .iter()
            .filter_map(|arg| expressions.get(arg.value))
            .map(|arg| simple_flow_mode_with_bindings(arg, expressions, bindings))
            .fold(FlowMode::Continuous, merge_flow_modes),
        AstExprKind::Pipe { op, .. } if matches!(op.as_str(), "Stream/pulses" | "Stream/skip") => {
            FlowMode::PresentOrAbsent
        }
        AstExprKind::Pipe {
            input, op, args, ..
        } if op != "WHILE" => args
            .iter()
            .filter_map(|arg| expressions.get(arg.value))
            .chain(expressions.get(*input))
            .map(|input| simple_flow_mode_with_bindings(input, expressions, bindings))
            .fold(FlowMode::Continuous, merge_flow_modes),
        AstExprKind::When { input, .. } | AstExprKind::Draining { input } => expressions
            .get(*input)
            .map(|input| simple_flow_mode_with_bindings(input, expressions, bindings))
            .unwrap_or(FlowMode::Continuous),
        _ => simple_flow_mode(expr, expressions),
    }
}

fn simple_flow_mode(expr: &AstExpr, expressions: &[AstExpr]) -> FlowMode {
    match &expr.kind {
        AstExprKind::Source | AstExprKind::Then { .. } => FlowMode::PresentOrAbsent,
        AstExprKind::Call { function, .. }
            if matches!(function.as_str(), "Stream/pulses" | "Stream/skip") =>
        {
            FlowMode::PresentOrAbsent
        }
        AstExprKind::When { input, .. } => expressions
            .get(*input)
            .map(|expr| simple_flow_mode(expr, expressions))
            .unwrap_or(FlowMode::Continuous),
        AstExprKind::Pipe { input, op, .. } if op == "WHILE" => {
            let _ = input;
            FlowMode::Continuous
        }
        AstExprKind::Pipe { op, .. } if matches!(op.as_str(), "Stream/pulses" | "Stream/skip") => {
            FlowMode::PresentOrAbsent
        }
        AstExprKind::Pipe { input, .. } => expressions
            .get(*input)
            .map(|expr| simple_flow_mode(expr, expressions))
            .unwrap_or(FlowMode::Continuous),
        AstExprKind::Draining { input } => expressions
            .get(*input)
            .map(|expr| simple_flow_mode(expr, expressions))
            .unwrap_or(FlowMode::Continuous),
        _ => FlowMode::Continuous,
    }
}

fn collect_name_bindings(
    statements: &[AstStatement],
    expressions: &[AstExpr],
    scope: &mut Vec<String>,
    source_payload_types: &BTreeMap<String, Type>,
    bindings: &mut BTreeMap<String, Type>,
) {
    for statement in statements {
        match &statement.kind {
            AstStatementKind::Field { name } if name == "document" => continue,
            AstStatementKind::Field { name } => {
                let path = scoped_path(scope, name);
                let ty = statement_value_type_from_bindings(statement, expressions, bindings)
                    .or_else(|| simple_statement_value_type(statement, expressions))
                    .unwrap_or_else(|| {
                        Type::object(object_shape_for_statement(statement, expressions))
                    });
                insert_simple_binding_preserving_renderable(bindings, name, ty.clone());
                if path != *name {
                    bindings.insert(path, ty);
                }
                scope.push(name.clone());
                collect_name_bindings(
                    &statement.children,
                    expressions,
                    scope,
                    source_payload_types,
                    bindings,
                );
                scope.pop();
            }
            AstStatementKind::Hold {
                name: Some(name), ..
            } => {
                if let Some(ty) =
                    statement_value_type_from_bindings(statement, expressions, bindings)
                        .or_else(|| simple_statement_value_type(statement, expressions))
                {
                    bindings.insert(name.clone(), ty);
                }
                collect_name_bindings(
                    &statement.children,
                    expressions,
                    scope,
                    source_payload_types,
                    bindings,
                );
            }
            AstStatementKind::List {
                field: Some(name), ..
            } => {
                let ty = simple_list_statement_type(statement, expressions);
                insert_simple_binding_preserving_renderable(bindings, name, ty.clone());
                let path = scoped_path(scope, name);
                if path != *name {
                    bindings.insert(path, ty);
                }
                collect_name_bindings(
                    &statement.children,
                    expressions,
                    scope,
                    source_payload_types,
                    bindings,
                );
            }
            AstStatementKind::Source {
                field: Some(name), ..
            } => {
                let source_path = scoped_path(scope, name);
                let ty = source_payload_type_for_path(source_payload_types, &source_path)
                    .unwrap_or_else(exact_empty_object_type);
                insert_simple_binding_preserving_renderable(bindings, name, ty.clone());
                if source_path != *name {
                    bindings.insert(source_path, ty);
                }
                collect_name_bindings(
                    &statement.children,
                    expressions,
                    scope,
                    source_payload_types,
                    bindings,
                );
            }
            AstStatementKind::Function { .. } => {
                collect_name_bindings(
                    &statement.children,
                    expressions,
                    scope,
                    source_payload_types,
                    bindings,
                );
            }
            _ => collect_name_bindings(
                &statement.children,
                expressions,
                scope,
                source_payload_types,
                bindings,
            ),
        }
    }
}

fn insert_simple_binding_preserving_renderable(
    bindings: &mut BTreeMap<String, Type>,
    name: &str,
    ty: Type,
) {
    if bindings.get(name).is_some_and(type_contains_renderable) && !type_contains_renderable(&ty) {
        return;
    }
    bindings.insert(name.to_owned(), ty);
}

fn type_has_known_user_shape(ty: &Type) -> bool {
    match ty {
        Type::Unknown | Type::UnresolvedShape { .. } => false,
        Type::Object(shape) => !shape.fields.is_empty(),
        Type::List(item) => type_has_known_user_shape(item),
        _ => true,
    }
}

fn list_item_type_from_list_type(ty: &Type) -> Option<Type> {
    match ty {
        Type::List(item) => Some((**item).clone()),
        _ => None,
    }
}

fn forwarded_parameter_requirement(projection: &[String], required: Type) -> Type {
    projection.iter().rev().fold(required, |child, field| {
        Type::object(ObjectShape::from_ordered_fields(
            [(field.clone(), child)],
            true,
        ))
    })
}

fn forwarded_parameter_requirement_for_path(
    path: &[ForwardedParameterPathSegment],
    required: Type,
) -> Type {
    path.iter()
        .rev()
        .fold(required, |child, segment| match segment {
            ForwardedParameterPathSegment::Field(field) => Type::object(
                ObjectShape::from_ordered_fields([(field.clone(), child)], true),
            ),
            ForwardedParameterPathSegment::ListItem => Type::List(Type::shared(child)),
        })
}

fn known_type_for_forwarded_parameter_path(
    base: &Type,
    path: &[ForwardedParameterPathSegment],
) -> Option<Type> {
    let Some((segment, rest)) = path.split_first() else {
        return Some(base.clone());
    };
    match (segment, base) {
        (ForwardedParameterPathSegment::Field(field), Type::Object(shape)) => {
            known_type_for_forwarded_parameter_path(shape.fields.get(field)?, rest)
        }
        (ForwardedParameterPathSegment::ListItem, Type::List(item)) => {
            known_type_for_forwarded_parameter_path(item, rest)
        }
        _ => None,
    }
}

fn merge_forwarded_parameter_type(caller: &Type, required: &Type) -> Type {
    match (caller, required) {
        (Type::Var(_), Type::Var(_)) => caller.clone(),
        (Type::Var(_), Type::Unknown | Type::UnresolvedShape { .. }) => caller.clone(),
        (Type::Var(_), required) => required.clone(),
        (Type::Unknown | Type::UnresolvedShape { .. }, required) => required.clone(),
        (caller, Type::Unknown | Type::UnresolvedShape { .. } | Type::Var(_)) => caller.clone(),
        (Type::Object(caller), Type::Object(required)) => {
            let mut fields = caller.fields.clone();
            for (field, required_ty) in required.ordered_fields() {
                fields
                    .entry(field.clone())
                    .and_modify(|caller_ty| {
                        *caller_ty = merge_forwarded_parameter_type(caller_ty, required_ty);
                    })
                    .or_insert_with(|| required_ty.clone());
            }
            Type::object(ObjectShape {
                fields,
                field_order: object_field_order_for_widened_shapes(caller, required),
                open: caller.open || required.open,
            })
        }
        (Type::List(caller), Type::List(required)) => Type::List(Type::shared(
            merge_forwarded_parameter_type(caller, required),
        )),
        _ => merge_canonical_row_type(caller, required),
    }
}

fn finalize_checked_call_occurrence_result(
    principal: &Type,
    occurrence: &Type,
    concrete_syntax_result: bool,
) -> Type {
    if concrete_syntax_result && type_has_concrete_outer_shape(occurrence) {
        // A heterogeneous syntax dispatcher can have a closed scalar public
        // summary while a concrete tagged request selects a record/list arm.
        // The checked fixed point has already evaluated that occurrence; do
        // not erase it while finalizing the callable's principal signature.
        occurrence.clone()
    } else {
        specialize_checked_call_result(principal, occurrence)
    }
}

fn merge_canonical_row_type(canonical: &Type, extra: &Type) -> Type {
    if is_value_placeholder_type(canonical) {
        return extra.clone();
    }
    if is_value_placeholder_type(extra) {
        return canonical.clone();
    }
    match (canonical, extra) {
        (Type::Object(canonical_shape), Type::Object(extra_shape)) => {
            let mut fields = canonical_shape.fields.clone();
            for (field, extra_ty) in extra_shape.ordered_fields() {
                fields
                    .entry(field.clone())
                    .and_modify(|existing| {
                        *existing = merge_canonical_row_type(existing, extra_ty);
                    })
                    .or_insert_with(|| extra_ty.clone());
            }
            Type::object(ObjectShape {
                fields,
                field_order: object_field_order_for_widened_shapes(canonical_shape, extra_shape),
                open: canonical_shape.open || extra_shape.open,
            })
        }
        (Type::List(canonical_item), Type::List(extra_item)) => Type::List(Type::shared(
            merge_canonical_row_type(canonical_item, extra_item),
        )),
        _ => widen_structural_type(canonical, extra),
    }
}

fn is_value_placeholder_type(ty: &Type) -> bool {
    match ty {
        Type::Unknown | Type::Var(_) | Type::UnresolvedShape { .. } => true,
        Type::Object(shape) => shape.open && shape.fields.is_empty(),
        _ => false,
    }
}

fn pattern_variable_names(pattern: &AstMatchPattern) -> Vec<String> {
    match pattern {
        AstMatchPattern::Binding { name } => vec![name.clone()],
        AstMatchPattern::Tag { fields, .. } => fields.clone(),
        AstMatchPattern::Wildcard
        | AstMatchPattern::Number { .. }
        | AstMatchPattern::Text { .. }
        | AstMatchPattern::Bits { .. } => Vec::new(),
        AstMatchPattern::Invalid { .. } => {
            unreachable!("invalid match patterns are rejected by boon_parser")
        }
    }
}

fn statements_define_explicit_record(statements: &[AstStatement], expressions: &[AstExpr]) -> bool {
    statements.iter().any(|statement| {
        if semantic_block_statement(statement, expressions) {
            return semantic_block_return_statement(&statement.children).is_some_and(|returned| {
                statements_define_explicit_record(std::slice::from_ref(returned), expressions)
            });
        }
        matches!(statement.kind, AstStatementKind::Block)
            && statement
                .children
                .iter()
                .any(|child| statement_field(child).is_some())
    })
}

fn semantic_block_statement(statement: &AstStatement, expressions: &[AstExpr]) -> bool {
    matches!(statement.kind, AstStatementKind::Block)
        && statement_has_block_value(statement, expressions)
}

fn statement_has_block_value(statement: &AstStatement, expressions: &[AstExpr]) -> bool {
    statement
        .expr
        .and_then(|expr_id| expressions.get(expr_id))
        .is_some_and(|expr| matches!(&expr.kind, AstExprKind::Block { .. }))
}

fn semantic_block_return_statement(statements: &[AstStatement]) -> Option<&AstStatement> {
    statements
        .iter()
        .rev()
        .find(|statement| statement_output_name(statement).is_none())
        .or_else(|| statements.last())
}

fn widen_structural_type(left: &Type, right: &Type) -> Type {
    if is_value_placeholder_type(left) {
        return right.clone();
    }
    if is_value_placeholder_type(right) {
        return left.clone();
    }
    match (left, right) {
        (Type::VariantSet(left), Type::VariantSet(right)) => {
            let mut variants = left.clone().into_owned();
            for variant in right {
                merge_structural_variant(&mut variants, variant.clone());
            }
            variants.sort_by_key(variant_sort_key);
            Type::VariantSet(variants.into())
        }
        (Type::Absent, ty) | (ty, Type::Absent) => ty.clone(),
        (ty, no_element) if is_no_element_type(no_element) => ty.clone(),
        (no_element, ty) if is_no_element_type(no_element) => ty.clone(),
        (Type::Text, Type::Text) => Type::Text,
        (Type::Number, Type::Number) => Type::Number,
        (Type::Bytes(left), Type::Bytes(right)) => match (left, right) {
            (BytesType::Fixed(left), BytesType::Fixed(right)) if left == right => {
                Type::Bytes(BytesType::Fixed(*left))
            }
            _ => Type::Bytes(BytesType::Dynamic),
        },
        (Type::Bits { width: left }, Type::Bits { width: right }) if left == right => {
            Type::Bits { width: *left }
        }
        (Type::List(left), Type::List(right)) => {
            Type::List(Type::shared(widen_structural_type(left, right)))
        }
        (Type::Object(left), Type::Object(right)) => {
            let mut fields = left.fields.clone();
            for (field, ty) in &right.fields {
                fields
                    .entry(field.clone())
                    .and_modify(|existing| *existing = widen_structural_type(existing, ty))
                    .or_insert_with(|| ty.clone());
            }
            Type::object(ObjectShape {
                fields,
                field_order: object_field_order_for_widened_shapes(left, right),
                open: left.open || right.open,
            })
        }
        _ => open_object_type(),
    }
}

fn union_structural_type(left: &Type, right: &Type) -> Type {
    canonical_union_type(vec![left.clone(), right.clone()])
}

fn merge_structural_variant(variants: &mut Vec<Variant>, incoming: Variant) {
    match incoming {
        Variant::Tag(incoming_tag) => {
            if !variants.iter().any(|variant| match variant {
                Variant::Tag(tag) | Variant::Tagged { tag, .. } => tag == &incoming_tag,
            }) {
                variants.push(Variant::Tag(incoming_tag));
            }
        }
        Variant::Tagged {
            tag: incoming_tag,
            fields: incoming_fields,
        } => {
            let Some(index) = variants.iter().position(|variant| match variant {
                Variant::Tag(tag) | Variant::Tagged { tag, .. } => tag == &incoming_tag,
            }) else {
                variants.push(Variant::Tagged {
                    tag: incoming_tag,
                    fields: incoming_fields,
                });
                return;
            };
            let fields = match &variants[index] {
                Variant::Tag(_) => incoming_fields,
                Variant::Tagged {
                    fields: existing_fields,
                    ..
                } => {
                    let merged = widen_structural_type(
                        &Type::Object(existing_fields.clone()),
                        &Type::Object(incoming_fields),
                    );
                    let Type::Object(fields) = merged else {
                        unreachable!("widening two tagged payload records must produce a record");
                    };
                    fields
                }
            };
            variants[index] = Variant::Tagged {
                tag: incoming_tag,
                fields,
            };
        }
    }
}

fn widen_hold_type(current: &Type, update: &Type) -> Type {
    if is_specific_type(current) && !is_specific_type(update) {
        current.clone()
    } else {
        widen_structural_type(current, update)
    }
}

fn widen_checked_hold_type(current: &Type, update: &Type) -> Type {
    if is_value_placeholder_type(update) {
        current.clone()
    } else if is_value_placeholder_type(current) {
        update.clone()
    } else {
        widen_hold_type(current, update)
    }
}

fn object_field_order_for_widened_shapes(left: &ObjectShape, right: &ObjectShape) -> Vec<String> {
    let mut order = Vec::new();
    let mut seen = BTreeSet::new();
    for field in left.field_order.iter().chain(right.field_order.iter()) {
        if (left.fields.contains_key(field) || right.fields.contains_key(field))
            && seen.insert(field.as_str())
        {
            order.push(field.clone());
        }
    }
    for field in left.fields.keys().chain(right.fields.keys()) {
        if seen.insert(field.as_str()) {
            order.push(field.clone());
        }
    }
    order
}

fn insert_ordered_shape_field(
    fields: &mut BTreeMap<String, Type>,
    field_order: &mut Vec<String>,
    field: String,
    ty: Type,
) {
    if !fields.contains_key(&field) {
        field_order.push(field.clone());
    }
    fields
        .entry(field)
        .and_modify(|existing| *existing = widen_structural_type(existing, &ty))
        .or_insert(ty);
}

fn merge_shape_override(
    fields: &mut BTreeMap<String, Type>,
    field_order: &mut Vec<String>,
    shape: &ObjectShape,
) {
    for (field, ty) in shape.ordered_fields() {
        insert_shape_field_override(fields, field_order, field.clone(), ty.clone());
    }
}

fn insert_shape_field_override(
    fields: &mut BTreeMap<String, Type>,
    field_order: &mut Vec<String>,
    field: String,
    ty: Type,
) {
    if !fields.contains_key(&field) {
        field_order.push(field.clone());
    }
    fields.insert(field, ty);
}

fn type_for_nested_path(base: &Type, parts: &[String]) -> Option<Type> {
    let Some((field, rest)) = parts.split_first() else {
        return Some(base.clone());
    };
    match base {
        Type::Object(shape) => {
            if let Some(field_ty) = shape.fields.get(field) {
                return type_for_nested_path(field_ty, rest);
            }
            if shape.open {
                return Some(open_object_type());
            }
            None
        }
        Type::Union(members) => members
            .iter()
            .filter_map(|member| type_for_nested_path(member, parts))
            .reduce(|existing, extra| union_structural_type(&existing, &extra)),
        Type::UnresolvedShape { .. } | Type::Unknown | Type::Var(_) => Some(base.clone()),
        _ => None,
    }
}

fn type_from_longest_binding_prefix(
    bindings: &dyn StaticBindingLookup,
    parts: &[String],
) -> Option<Type> {
    for prefix_len in (1..=parts.len()).rev() {
        let prefix = boon_syntax::canonical_value_path(&parts[..prefix_len]);
        let Some(base) = bindings.static_binding(&prefix) else {
            continue;
        };
        if let Some(ty) = type_for_nested_path(base, &parts[prefix_len..]) {
            return Some(ty);
        }
    }
    None
}

fn drain_path_parts(path: &AstDrainPath) -> Vec<String> {
    match path {
        AstDrainPath::Binding { name } => vec![name.clone()],
        AstDrainPath::Field { binding, fields } => std::iter::once(binding.clone())
            .chain(fields.iter().cloned())
            .collect(),
        AstDrainPath::Passed { fields } => std::iter::once("PASSED".to_owned())
            .chain(fields.iter().cloned())
            .collect(),
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum SourcePayloadAccess {
    Direct(String),
    Field(String),
    UnknownField(String),
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct SyntaxSourceSite {
    statement: usize,
    expression: usize,
    path: String,
    projection: Vec<String>,
    interval_ms: Option<u64>,
}

fn syntax_source_sites(program: &ParsedProgram) -> Vec<SyntaxSourceSite> {
    fn collect_statements(
        statements: &[AstStatement],
        expressions: &[AstExpr],
        scope: &mut Vec<String>,
        sources: &mut Vec<SyntaxSourceSite>,
    ) {
        for statement in statements {
            let scope_len = scope.len();
            match &statement.kind {
                AstStatementKind::Function { name, .. } => {
                    scope.push(format!("FUNCTION:{name}"));
                }
                AstStatementKind::Field { name }
                | AstStatementKind::Source {
                    field: Some(name), ..
                }
                | AstStatementKind::Hold {
                    field: Some(name), ..
                }
                | AstStatementKind::List {
                    field: Some(name), ..
                } => scope.push(name.clone()),
                AstStatementKind::Source { field: None, .. }
                | AstStatementKind::Hold { field: None, .. }
                | AstStatementKind::List { field: None, .. }
                | AstStatementKind::Block
                | AstStatementKind::Spread
                | AstStatementKind::Expression => {}
            }
            if let Some(expression) = statement.expr {
                collect_source_expressions(
                    expression,
                    statement.id,
                    expressions,
                    scope,
                    &mut Vec::new(),
                    sources,
                );
            }
            collect_statements(&statement.children, expressions, scope, sources);
            scope.truncate(scope_len);
        }
    }

    fn collect_source_expressions(
        expression: usize,
        statement: usize,
        expressions: &[AstExpr],
        scope: &[String],
        projection: &mut Vec<String>,
        sources: &mut Vec<SyntaxSourceSite>,
    ) {
        let Some(expr) = expressions.get(expression) else {
            return;
        };
        let interval_ms = match &expr.kind {
            AstExprKind::Source => None,
            AstExprKind::Pipe { input, op, .. } if op == "Timer/interval" => {
                duration_milliseconds(*input, expressions)
            }
            _ => {
                match &expr.kind {
                    AstExprKind::Object(fields) | AstExprKind::TaggedObject { fields, .. } => {
                        for field in fields {
                            let projection_len = projection.len();
                            if !field.spread {
                                projection.push(field.name.clone());
                            }
                            collect_source_expressions(
                                field.value,
                                statement,
                                expressions,
                                scope,
                                projection,
                                sources,
                            );
                            projection.truncate(projection_len);
                        }
                    }
                    _ => {
                        for child in direct_expression_children(expr) {
                            collect_source_expressions(
                                child,
                                statement,
                                expressions,
                                scope,
                                projection,
                                sources,
                            );
                        }
                    }
                }
                return;
            }
        };
        let path = scope
            .iter()
            .chain(projection.iter())
            .cloned()
            .collect::<Vec<_>>()
            .join(".");
        if path.is_empty() {
            return;
        }
        let source = SyntaxSourceSite {
            statement,
            expression,
            path,
            projection: projection.clone(),
            interval_ms,
        };
        if !sources.contains(&source) {
            sources.push(source);
        }
    }

    let mut sources = Vec::new();
    collect_statements(
        &program.ast.statements,
        &program.expressions,
        &mut Vec::new(),
        &mut sources,
    );
    sources.sort_by_key(|source| {
        (
            source.expression,
            source.projection.len(),
            source.path.clone(),
            source.statement,
        )
    });
    sources.dedup_by_key(|source| source.expression);
    sources
}

fn duration_milliseconds(expression: usize, expressions: &[AstExpr]) -> Option<u64> {
    let AstExprKind::TaggedObject { tag, fields } = &expressions.get(expression)?.kind else {
        return None;
    };
    if tag != "Duration" {
        return None;
    }
    fields.iter().find_map(|field| {
        let scale = match field.name.as_str() {
            "milliseconds" => 1,
            "seconds" => 1_000,
            _ => return None,
        };
        let AstExprKind::Number(value) = &expressions.get(field.value)?.kind else {
            return None;
        };
        ExactNumber::parse_strict(value, None)
            .ok()
            .and_then(|value| exact_duration_milliseconds(&value, scale))
    })
}

fn checked_duration_milliseconds(
    expression: CheckedExprId,
    expressions: &[CheckedExpression],
) -> Option<u64> {
    let CheckedExpressionKind::TaggedObject { tag, fields } = &expressions
        .get(expression.0 as usize)
        .filter(|candidate| candidate.id == expression)?
        .kind
    else {
        return None;
    };
    if tag != "Duration" {
        return None;
    }
    fields.iter().find_map(|field| {
        let scale = match field.name.as_str() {
            "milliseconds" => 1,
            "seconds" => 1_000,
            _ => return None,
        };
        let CheckedExpressionKind::Number { value } = &expressions
            .get(field.value.0 as usize)
            .filter(|candidate| candidate.id == field.value)?
            .kind
        else {
            return None;
        };
        exact_duration_milliseconds(value, scale)
    })
}

fn exact_duration_milliseconds(value: &ExactNumber, scale: u64) -> Option<u64> {
    value
        .checked_mul(&ExactNumber::from_u64(scale))
        .ok()?
        .to_u64_exact()
        .ok()
}

/// Longest-prefix source lookup indexed once per checked program. The old
/// helper filtered, allocated, and sorted the entire source table for every
/// read and every provenance traversal.
struct CheckedSourcePathIndex<'a> {
    by_anchor: BTreeMap<DeclId, Vec<&'a CheckedSource>>,
}

impl<'a> CheckedSourcePathIndex<'a> {
    fn new(sources: &'a [CheckedSource]) -> Self {
        let mut by_anchor = BTreeMap::<DeclId, Vec<&CheckedSource>>::new();
        for source in sources {
            by_anchor
                .entry(source.path.anchor)
                .or_default()
                .push(source);
        }
        for candidates in by_anchor.values_mut() {
            candidates.sort_by_key(|source| std::cmp::Reverse(source.path.projection.len()));
        }
        Self { by_anchor }
    }

    fn exact_read(&self, target: DeclId, projection: &[String]) -> Option<CheckedSourceRead> {
        let mut matches = self.by_anchor.get(&target)?.iter().filter_map(|source| {
            projection
                .strip_prefix(source.path.projection.as_slice())
                .map(|payload| (*source, payload))
        });
        let (source, payload) = matches.next()?;
        if matches.next().is_some_and(|(candidate, _)| {
            candidate.path.projection.len() == source.path.projection.len()
        }) {
            return None;
        }
        Some(CheckedSourceRead {
            source: source.id,
            payload_projection: canonical_checked_source_payload_projection(payload),
        })
    }
}

fn canonical_checked_source_payload_projection(projection: &[String]) -> Vec<String> {
    if projection.is_empty() {
        return Vec::new();
    }
    let suffix = projection.join(".");
    match source_payload_access_for_suffix(&suffix) {
        SourcePayloadAccess::Field(field) => vec![field],
        SourcePayloadAccess::Direct(_) | SourcePayloadAccess::UnknownField(_) => projection
            .strip_prefix(&["event".to_owned()])
            .or_else(|| projection.strip_prefix(&["events".to_owned()]))
            .unwrap_or(projection)
            .to_vec(),
    }
}

fn refine_checked_source_payload_types(
    sources: &mut [CheckedSource],
    expressions: &[CheckedExpression],
) {
    let mut requirements = BTreeMap::<CheckedSourceId, BTreeMap<Vec<String>, Type>>::new();
    for expression in expressions {
        let CheckedExpressionKind::Read {
            source: Some(source),
            ..
        } = &expression.kind
        else {
            continue;
        };
        let Some(field) = source.payload_projection.first() else {
            continue;
        };
        let leaf_type = if matches!(
            expression.flow_type.ty,
            Type::Unknown | Type::UnresolvedShape { .. } | Type::Var(_)
        ) {
            source_payload_field_type(field)
        } else {
            expression.flow_type.ty.clone()
        };
        requirements
            .entry(source.source)
            .or_default()
            .entry(source.payload_projection.clone())
            .and_modify(|existing| {
                *existing = merge_source_payload_structural_requirement(existing, &leaf_type);
            })
            .or_insert(leaf_type);
    }

    for source in sources {
        let mut shape = match &source.payload_type {
            Type::Object(shape) => shape.as_ref().clone(),
            _ => ObjectShape {
                fields: BTreeMap::new(),
                field_order: Vec::new(),
                open: false,
            },
        };
        for (path, ty) in requirements.remove(&source.id).unwrap_or_default() {
            insert_source_payload_requirement_path(&mut shape, &path, &ty);
        }
        source.payload_type = Type::object(shape);
    }
}

fn checked_resource_projection_requirements(
    declarations: &[CheckedDeclaration],
    callables: &[CheckedCallableSignature],
    calls: &[CheckedCall],
    expressions: &[CheckedExpression],
    sources: &[CheckedSource],
) -> Vec<CheckedResourceProjectionRequirement> {
    let mut resolver =
        CheckedSourceProvenanceResolver::new(declarations, callables, calls, expressions, sources);
    expressions
        .iter()
        .filter_map(|expression| {
            let (target, projection) = match &expression.kind {
                CheckedExpressionKind::Read {
                    target,
                    projection,
                    source: None,
                }
                | CheckedExpressionKind::Drain { target, projection } => (*target, projection),
                _ => return None,
            };
            let required_type = if !is_specific_type(&expression.flow_type.ty) {
                projection
                    .last()
                    .map_or(Type::Unknown, |field| source_payload_field_type(field))
            } else {
                expression.flow_type.ty.clone()
            };
            (!projection.is_empty()).then(|| CheckedResourceProjectionRequirement {
                expression: expression.id,
                target,
                projection: projection.clone(),
                source_origins: resolver.sources_for_declaration(target, projection),
                required_type,
            })
        })
        .collect()
}

fn refine_checked_source_payload_types_from_requirements(
    sources: &mut [CheckedSource],
    requirements: &[CheckedResourceProjectionRequirement],
) {
    let mut payloads = BTreeMap::<CheckedSourceId, BTreeMap<Vec<String>, Type>>::new();
    for requirement in requirements {
        for origin in &requirement.source_origins {
            if origin.payload_projection.is_empty() {
                continue;
            }
            payloads
                .entry(origin.source)
                .or_default()
                .entry(origin.payload_projection.clone())
                .and_modify(|existing| {
                    *existing = merge_source_payload_structural_requirement(
                        existing,
                        &requirement.required_type,
                    );
                })
                .or_insert_with(|| requirement.required_type.clone());
        }
    }
    for source in sources {
        let mut shape = match &source.payload_type {
            Type::Object(shape) => shape.as_ref().clone(),
            _ => ObjectShape {
                fields: BTreeMap::new(),
                field_order: Vec::new(),
                open: false,
            },
        };
        for (path, ty) in payloads.remove(&source.id).unwrap_or_default() {
            insert_source_payload_requirement_path(&mut shape, &path, &ty);
        }
        source.payload_type = Type::object(shape);
    }
}

#[derive(Clone, Debug, Eq, Ord, PartialEq, PartialOrd)]
enum CheckedSourceResolution {
    Declaration(DeclId, Vec<String>),
    Expression(CheckedExprId, Vec<String>),
    ListItem(CheckedExprId, Vec<String>),
    Output(DeclId, Vec<String>),
}

struct CheckedSourceProvenanceResolver<'a> {
    declarations: BTreeMap<DeclId, &'a CheckedDeclaration>,
    callables: BTreeMap<DeclId, &'a CheckedCallableSignature>,
    calls: BTreeMap<CheckedCallId, &'a CheckedCall>,
    expressions: BTreeMap<CheckedExprId, &'a CheckedExpression>,
    source_paths: CheckedSourcePathIndex<'a>,
    source_expressions: BTreeMap<CheckedExprId, Vec<CheckedSourceId>>,
    actual_inputs_by_formal: BTreeMap<DeclId, Vec<CheckedExprId>>,
    contextual_lists_by_output: BTreeMap<DeclId, Vec<CheckedExprId>>,
    forwarded_outputs_by_formal: BTreeMap<DeclId, Vec<DeclId>>,
    declaration_cache: BTreeMap<(DeclId, Vec<String>), Vec<CheckedSourceRead>>,
}

impl<'a> CheckedSourceProvenanceResolver<'a> {
    fn new(
        declarations: &'a [CheckedDeclaration],
        callables: &'a [CheckedCallableSignature],
        calls: &'a [CheckedCall],
        expressions: &'a [CheckedExpression],
        sources: &'a [CheckedSource],
    ) -> Self {
        let callable_index = callables
            .iter()
            .map(|callable| (callable.decl_id, callable))
            .collect::<BTreeMap<_, _>>();
        let mut source_expressions = BTreeMap::<CheckedExprId, Vec<CheckedSourceId>>::new();
        for source in sources {
            source_expressions
                .entry(source.expression)
                .or_default()
                .push(source.id);
        }
        let mut actual_inputs_by_formal = BTreeMap::<DeclId, Vec<CheckedExprId>>::new();
        let mut contextual_lists_by_output = BTreeMap::<DeclId, Vec<CheckedExprId>>::new();
        let mut forwarded_outputs_by_formal = BTreeMap::<DeclId, Vec<DeclId>>::new();
        for call in calls {
            let mut indexed_input_formals = BTreeSet::new();
            for entry in &call.entries {
                match entry {
                    CheckedCallEntry::Input { formal, value, .. } => {
                        // `checked_call_formal_input` has always selected the
                        // first input for a formal within one call. Preserve
                        // that fail-closed malformed-call behavior exactly.
                        if indexed_input_formals.insert(*formal) {
                            actual_inputs_by_formal
                                .entry(*formal)
                                .or_default()
                                .push(*value);
                        }
                    }
                    CheckedCallEntry::FreshOut { formal, output, .. }
                    | CheckedCallEntry::ForwardOut {
                        formal,
                        target: output,
                        ..
                    } => {
                        forwarded_outputs_by_formal
                            .entry(*formal)
                            .or_default()
                            .push(*output);
                    }
                }
            }
            let Some(operation) = callable_index
                .get(&call.callable)
                .and_then(|callable| callable.contextual_operation)
            else {
                continue;
            };
            let Some((list_formal, row_formal, _)) =
                checked_contextual_operation_formals(operation)
            else {
                continue;
            };
            let Some(list) = checked_call_formal_input(call, list_formal) else {
                continue;
            };
            for entry in &call.entries {
                let output = match entry {
                    CheckedCallEntry::FreshOut { formal, output, .. } if *formal == row_formal => {
                        Some(*output)
                    }
                    CheckedCallEntry::ForwardOut {
                        formal,
                        target: output,
                        ..
                    } if *formal == row_formal => Some(*output),
                    _ => None,
                };
                if let Some(output) = output {
                    contextual_lists_by_output
                        .entry(output)
                        .or_default()
                        .push(list);
                }
            }
        }
        Self {
            declarations: declarations
                .iter()
                .map(|declaration| (declaration.id, declaration))
                .collect(),
            callables: callable_index,
            calls: calls.iter().map(|call| (call.id, call)).collect(),
            expressions: expressions
                .iter()
                .map(|expression| (expression.id, expression))
                .collect(),
            source_paths: CheckedSourcePathIndex::new(sources),
            source_expressions,
            actual_inputs_by_formal,
            contextual_lists_by_output,
            forwarded_outputs_by_formal,
            declaration_cache: BTreeMap::new(),
        }
    }

    fn sources_for_declaration(
        &mut self,
        target: DeclId,
        projection: &[String],
    ) -> Vec<CheckedSourceRead> {
        let key = (target, projection.to_vec());
        if let Some(cached) = self.declaration_cache.get(&key) {
            return cached.clone();
        }
        let resolved = self
            .declaration_sources(target, projection, &mut BTreeSet::new())
            .into_iter()
            .collect::<Vec<_>>();
        self.declaration_cache.insert(key, resolved.clone());
        resolved
    }

    fn declaration_sources(
        &self,
        target: DeclId,
        projection: &[String],
        visiting: &mut BTreeSet<CheckedSourceResolution>,
    ) -> BTreeSet<CheckedSourceRead> {
        let key = CheckedSourceResolution::Declaration(target, projection.to_vec());
        if !visiting.insert(key.clone()) {
            return BTreeSet::new();
        }
        let mut resolved = BTreeSet::new();
        if let Some(source) = self.source_paths.exact_read(target, projection) {
            resolved.insert(source);
        }
        let Some(declaration) = self.declarations.get(&target).copied() else {
            visiting.remove(&key);
            return resolved;
        };
        if declaration.kind == CheckedDeclarationKind::ValueParameter {
            for actual in self
                .actual_inputs_by_formal
                .get(&target)
                .into_iter()
                .flatten()
            {
                resolved.extend(self.expression_sources(*actual, projection, visiting));
            }
        }
        if matches!(
            declaration.kind,
            CheckedDeclarationKind::FreshOut | CheckedDeclarationKind::OutParameter
        ) {
            resolved.extend(self.output_sources(target, projection, visiting));
        }
        if let Some(value) = declaration.value {
            resolved.extend(self.expression_sources(value, projection, visiting));
        }
        if let Some(result) = self
            .callables
            .get(&target)
            .and_then(|callable| callable.result_expression)
        {
            resolved.extend(self.expression_sources(result, projection, visiting));
        }
        visiting.remove(&key);
        resolved
    }

    fn expression_sources(
        &self,
        expression_id: CheckedExprId,
        projection: &[String],
        visiting: &mut BTreeSet<CheckedSourceResolution>,
    ) -> BTreeSet<CheckedSourceRead> {
        let key = CheckedSourceResolution::Expression(expression_id, projection.to_vec());
        if !visiting.insert(key.clone()) {
            return BTreeSet::new();
        }
        let mut resolved = BTreeSet::new();
        if let Some(sources) = self.source_expressions.get(&expression_id) {
            resolved.extend(sources.iter().map(|source| CheckedSourceRead {
                source: *source,
                payload_projection: canonical_checked_source_payload_projection(projection),
            }));
            visiting.remove(&key);
            return resolved;
        }
        let Some(expression) = self.expressions.get(&expression_id).copied() else {
            visiting.remove(&key);
            return resolved;
        };
        match &expression.kind {
            CheckedExpressionKind::Read {
                target,
                projection: read_projection,
                ..
            }
            | CheckedExpressionKind::Drain {
                target,
                projection: read_projection,
            } => {
                let mut combined = read_projection.clone();
                combined.extend_from_slice(projection);
                resolved.extend(self.declaration_sources(*target, &combined, visiting));
            }
            CheckedExpressionKind::TaggedObject { fields, .. }
            | CheckedExpressionKind::Object { fields } => {
                if let Some((field, rest)) = projection.split_first() {
                    for candidate in fields.iter().filter(|candidate| candidate.name == *field) {
                        resolved.extend(self.expression_sources(candidate.value, rest, visiting));
                    }
                }
            }
            CheckedExpressionKind::Call { call } => {
                if let Some(call) = self.calls.get(call).copied()
                    && let Some(callable) = self.callables.get(&call.callable).copied()
                {
                    if callable.kind == CheckedCallableKind::User {
                        if let Some(result) = callable.result_expression {
                            resolved.extend(self.expression_sources(result, projection, visiting));
                        }
                    } else if (matches!(
                        callable.contextual_operation,
                        Some(CheckedContextualOperation::Find { .. })
                    ) || matches!(
                        call.function.as_str(),
                        "List/get" | "List/latest" | "List/find"
                    )) && let Some(list) = checked_call_input(call, "list")
                    {
                        resolved.extend(self.list_item_sources(list, projection, visiting));
                    }
                }
            }
            CheckedExpressionKind::Draining { input }
            | CheckedExpressionKind::Hold { initial: input, .. } => {
                resolved.extend(self.expression_sources(*input, projection, visiting));
            }
            CheckedExpressionKind::Flush { payload } => {
                resolved.extend(self.expression_sources(*payload, projection, visiting));
            }
            CheckedExpressionKind::Latest { branches } => {
                for branch in branches {
                    resolved.extend(self.expression_sources(*branch, projection, visiting));
                }
            }
            CheckedExpressionKind::When { arms, .. }
            | CheckedExpressionKind::While { arms, .. } => {
                for arm in arms {
                    resolved.extend(self.expression_sources(*arm, projection, visiting));
                }
            }
            CheckedExpressionKind::Then { output, .. }
            | CheckedExpressionKind::MatchArm { output, .. } => {
                if let Some(output) = output {
                    resolved.extend(self.expression_sources(*output, projection, visiting));
                }
            }
            CheckedExpressionKind::Block { result, .. } => {
                if let Some(result) = result {
                    resolved.extend(self.expression_sources(*result, projection, visiting));
                }
            }
            CheckedExpressionKind::MapEntry { key, value } => {
                resolved.extend(self.expression_sources(*key, &[], visiting));
                resolved.extend(self.expression_sources(*value, projection, visiting));
            }
            CheckedExpressionKind::Map { entries } => {
                for entry in entries {
                    resolved.extend(self.expression_sources(*entry, projection, visiting));
                }
            }
            CheckedExpressionKind::Set { items } => {
                for item in items {
                    resolved.extend(self.expression_sources(*item, projection, visiting));
                }
            }
            CheckedExpressionKind::List { .. }
            | CheckedExpressionKind::Passed { .. }
            | CheckedExpressionKind::ExternalRead { .. }
            | CheckedExpressionKind::Text { .. }
            | CheckedExpressionKind::TextTemplate { .. }
            | CheckedExpressionKind::Number { .. }
            | CheckedExpressionKind::Bits { .. }
            | CheckedExpressionKind::BytesByte { .. }
            | CheckedExpressionKind::Absent
            | CheckedExpressionKind::Tag { .. }
            | CheckedExpressionKind::Source
            | CheckedExpressionKind::Infix { .. }
            | CheckedExpressionKind::Bytes { .. }
            | CheckedExpressionKind::Delimiter
            | CheckedExpressionKind::Invalid { .. } => {}
        }
        visiting.remove(&key);
        resolved
    }

    fn list_item_sources(
        &self,
        expression_id: CheckedExprId,
        projection: &[String],
        visiting: &mut BTreeSet<CheckedSourceResolution>,
    ) -> BTreeSet<CheckedSourceRead> {
        let key = CheckedSourceResolution::ListItem(expression_id, projection.to_vec());
        if !visiting.insert(key.clone()) {
            return BTreeSet::new();
        }
        let mut resolved = BTreeSet::new();
        let Some(expression) = self.expressions.get(&expression_id).copied() else {
            visiting.remove(&key);
            return resolved;
        };
        match &expression.kind {
            CheckedExpressionKind::List { items, .. } => {
                for item in items {
                    resolved.extend(self.expression_sources(*item, projection, visiting));
                }
            }
            CheckedExpressionKind::Read {
                target,
                projection: list_projection,
                ..
            } => {
                if list_projection.is_empty()
                    && let Some(declaration) = self.declarations.get(target).copied()
                {
                    if declaration.kind == CheckedDeclarationKind::ValueParameter {
                        for actual in self
                            .actual_inputs_by_formal
                            .get(target)
                            .into_iter()
                            .flatten()
                        {
                            resolved.extend(self.list_item_sources(*actual, projection, visiting));
                        }
                    }
                    if let Some(value) = declaration.value {
                        resolved.extend(self.list_item_sources(value, projection, visiting));
                    }
                }
            }
            CheckedExpressionKind::Call { call } => {
                if let Some(call) = self.calls.get(call).copied()
                    && let Some(callable) = self.callables.get(&call.callable).copied()
                {
                    if callable.kind == CheckedCallableKind::User {
                        if let Some(result) = callable.result_expression {
                            resolved.extend(self.list_item_sources(result, projection, visiting));
                        }
                    } else {
                        match callable.contextual_operation {
                            Some(CheckedContextualOperation::Map { body, .. }) => {
                                if let Some(body) = checked_call_formal_input(call, body) {
                                    resolved.extend(
                                        self.expression_sources(body, projection, visiting),
                                    );
                                }
                            }
                            Some(
                                CheckedContextualOperation::Filter { list, .. }
                                | CheckedContextualOperation::Retain { list, .. }
                                | CheckedContextualOperation::Remove { list, .. }
                                | CheckedContextualOperation::SortBy { list, .. }
                                | CheckedContextualOperation::ThenBy { list, .. },
                            ) => {
                                if let Some(list) = checked_call_formal_input(call, list) {
                                    resolved
                                        .extend(self.list_item_sources(list, projection, visiting));
                                }
                            }
                            Some(
                                CheckedContextualOperation::Every { .. }
                                | CheckedContextualOperation::Any { .. }
                                | CheckedContextualOperation::Find { .. },
                            )
                            | None => {
                                if matches!(call.function.as_str(), "List/take" | "List/page")
                                    && let Some(list) = checked_call_input(call, "list")
                                {
                                    resolved
                                        .extend(self.list_item_sources(list, projection, visiting));
                                }
                            }
                        }
                    }
                }
            }
            CheckedExpressionKind::Draining { input }
            | CheckedExpressionKind::Hold { initial: input, .. } => {
                resolved.extend(self.list_item_sources(*input, projection, visiting));
            }
            CheckedExpressionKind::Latest { branches } => {
                for branch in branches {
                    resolved.extend(self.list_item_sources(*branch, projection, visiting));
                }
            }
            CheckedExpressionKind::When { arms, .. }
            | CheckedExpressionKind::While { arms, .. } => {
                for arm in arms {
                    resolved.extend(self.list_item_sources(*arm, projection, visiting));
                }
            }
            CheckedExpressionKind::Then { output, .. }
            | CheckedExpressionKind::MatchArm { output, .. } => {
                if let Some(output) = output {
                    resolved.extend(self.list_item_sources(*output, projection, visiting));
                }
            }
            CheckedExpressionKind::Block { result, .. } => {
                if let Some(result) = result {
                    resolved.extend(self.list_item_sources(*result, projection, visiting));
                }
            }
            CheckedExpressionKind::TaggedObject { .. }
            | CheckedExpressionKind::Object { .. }
            | CheckedExpressionKind::MapEntry { .. }
            | CheckedExpressionKind::Map { .. }
            | CheckedExpressionKind::Set { .. }
            | CheckedExpressionKind::Passed { .. }
            | CheckedExpressionKind::ExternalRead { .. }
            | CheckedExpressionKind::Drain { .. }
            | CheckedExpressionKind::Text { .. }
            | CheckedExpressionKind::TextTemplate { .. }
            | CheckedExpressionKind::Number { .. }
            | CheckedExpressionKind::Bits { .. }
            | CheckedExpressionKind::BytesByte { .. }
            | CheckedExpressionKind::Absent
            | CheckedExpressionKind::Flush { .. }
            | CheckedExpressionKind::Tag { .. }
            | CheckedExpressionKind::Source
            | CheckedExpressionKind::Infix { .. }
            | CheckedExpressionKind::Bytes { .. }
            | CheckedExpressionKind::Delimiter
            | CheckedExpressionKind::Invalid { .. } => {}
        }
        visiting.remove(&key);
        resolved
    }

    fn output_sources(
        &self,
        target: DeclId,
        projection: &[String],
        visiting: &mut BTreeSet<CheckedSourceResolution>,
    ) -> BTreeSet<CheckedSourceRead> {
        let key = CheckedSourceResolution::Output(target, projection.to_vec());
        if !visiting.insert(key.clone()) {
            return BTreeSet::new();
        }
        let mut resolved = BTreeSet::new();
        for list in self
            .contextual_lists_by_output
            .get(&target)
            .into_iter()
            .flatten()
        {
            resolved.extend(self.list_item_sources(*list, projection, visiting));
        }
        for output in self
            .forwarded_outputs_by_formal
            .get(&target)
            .into_iter()
            .flatten()
        {
            resolved.extend(self.output_sources(*output, projection, visiting));
        }
        visiting.remove(&key);
        resolved
    }
}

fn checked_call_formal_input(call: &CheckedCall, formal: DeclId) -> Option<CheckedExprId> {
    call.entries.iter().find_map(|entry| match entry {
        CheckedCallEntry::Input {
            formal: candidate,
            value,
            ..
        } if *candidate == formal => Some(*value),
        CheckedCallEntry::Input { .. }
        | CheckedCallEntry::FreshOut { .. }
        | CheckedCallEntry::ForwardOut { .. } => None,
    })
}

fn checked_source_payload_shape_table(program: &CheckedProgram) -> Vec<SourcePayloadShapeEntry> {
    let mut payloads = BTreeMap::<String, (Vec<CheckedSourceId>, Type)>::new();
    for source in &program.sources {
        let Some(path) = program.semantic_path(&source.path) else {
            continue;
        };
        payloads
            .entry(path)
            .and_modify(|(sources, existing)| {
                sources.push(source.id);
                *existing =
                    merge_source_payload_structural_requirement(existing, &source.payload_type);
            })
            .or_insert_with(|| (vec![source.id], source.payload_type.clone()));
    }
    let mut entries = payloads
        .into_iter()
        .map(|(diagnostic_path, (mut checked_sources, payload_type))| {
            checked_sources.sort();
            checked_sources.dedup();
            let fields = match &payload_type {
                Type::Object(shape) => shape
                    .field_order
                    .iter()
                    .filter_map(|name| {
                        shape.fields.get(name).map(|ty| SourcePayloadShapeField {
                            name: name.clone(),
                            ty: ty.clone(),
                        })
                    })
                    .collect(),
                _ => Vec::new(),
            };
            SourcePayloadShapeEntry {
                checked_sources,
                diagnostic_path,
                payload_type,
                fields,
            }
        })
        .collect::<Vec<_>>();
    entries.sort_by_key(|entry| entry.checked_sources.first().copied());
    entries
}

fn validate_checked_host_port_source_payload_types(
    program: &CheckedProgram,
    host_ports: &HostPortSyntaxTable,
) -> Result<(), String> {
    let host_payloads = host_port_payload_types(host_ports);
    for source in &program.sources {
        let Some(path) = program.semantic_path(&source.path) else {
            continue;
        };
        let Some(fields) = host_payloads.get(&path) else {
            continue;
        };
        let contract = Type::object(ObjectShape::from_ordered_fields(
            fields.iter().map(|(name, ty)| (name.clone(), ty.clone())),
            false,
        ));
        if source.payload_type != contract {
            return Err(format!(
                "checked host source {} `{path}` payload differs from its exact host contract\nexpected: {contract:?}\nfound: {:?}",
                source.id.0, source.payload_type,
            ));
        }
    }
    Ok(())
}

fn checked_statement_declaration(kind: &CheckedStatementKind) -> Option<DeclId> {
    match kind {
        CheckedStatementKind::Function { declaration }
        | CheckedStatementKind::Field { declaration } => Some(*declaration),
        CheckedStatementKind::Source { declaration, .. }
        | CheckedStatementKind::Hold { declaration, .. }
        | CheckedStatementKind::List { declaration, .. } => *declaration,
        CheckedStatementKind::Block
        | CheckedStatementKind::Spread
        | CheckedStatementKind::Expression => None,
    }
}

fn checked_call_result_paths(
    declarations: &[CheckedDeclaration],
    callables: &[CheckedCallableSignature],
    expressions: &[CheckedExpression],
    calls: &[CheckedCall],
) -> Vec<CheckedCallResultPath> {
    let declaration_values = declarations
        .iter()
        .filter_map(|declaration| {
            declaration
                .value
                .map(|value| (declaration.id, (value, declaration.flow_type.clone())))
        })
        .collect::<BTreeMap<_, _>>();
    let callables_by_id = callables
        .iter()
        .map(|callable| (callable.decl_id, callable))
        .collect::<BTreeMap<_, _>>();
    let calls_by_id = calls
        .iter()
        .map(|call| (call.id, call))
        .collect::<BTreeMap<_, _>>();
    let mut paths = calls
        .iter()
        .filter_map(|call| {
            let expression = expressions
                .get(call.expression.0 as usize)
                .filter(|expression| expression.id == call.expression)?;
            let anchor = expression.declaration?;
            checked_declaration_resource_projection(
                &callables_by_id,
                &declaration_values,
                expressions,
                &calls_by_id,
                anchor,
                call.expression,
            )
            .map(|projection| CheckedCallResultPath {
                call: call.id,
                path: CheckedSemanticPath { anchor, projection },
            })
        })
        .collect::<Vec<_>>();
    paths.sort_by_key(|path| path.call);
    paths
}

fn checked_declaration_resource_projection(
    callables: &BTreeMap<DeclId, &CheckedCallableSignature>,
    declaration_values: &BTreeMap<DeclId, (CheckedExprId, FlowType)>,
    expressions: &[CheckedExpression],
    calls: &BTreeMap<CheckedCallId, &CheckedCall>,
    declaration: DeclId,
    target: CheckedExprId,
) -> Option<Vec<String>> {
    let root = declaration_values
        .get(&declaration)
        .map(|(root, _)| *root)
        .or_else(|| {
            callables
                .get(&declaration)
                .and_then(|callable| callable.result_expression)
        })?;
    checked_projection_to_expression(expressions, calls, root, target)
}

fn checked_projection_to_expression(
    expressions: &[CheckedExpression],
    calls: &BTreeMap<CheckedCallId, &CheckedCall>,
    root: CheckedExprId,
    target: CheckedExprId,
) -> Option<Vec<String>> {
    fn visit(
        expressions: &[CheckedExpression],
        calls: &BTreeMap<CheckedCallId, &CheckedCall>,
        current: CheckedExprId,
        target: CheckedExprId,
        visiting: &mut BTreeSet<CheckedExprId>,
    ) -> Option<Vec<String>> {
        if current == target {
            return Some(Vec::new());
        }
        if !visiting.insert(current) {
            return None;
        }
        let expression = expressions
            .get(current.0 as usize)
            .filter(|expression| expression.id == current)?;
        let direct =
            |child, visiting: &mut BTreeSet<_>| visit(expressions, calls, child, target, visiting);
        let result = match &expression.kind {
            CheckedExpressionKind::TaggedObject { fields, .. }
            | CheckedExpressionKind::Object { fields } => fields.iter().find_map(|field| {
                let mut projection = direct(field.value, visiting)?;
                projection.insert(0, field.name.clone());
                Some(projection)
            }),
            CheckedExpressionKind::Call { call } => calls
                .get(call)
                .into_iter()
                .flat_map(|call| &call.entries)
                .find_map(|entry| match entry {
                    CheckedCallEntry::Input { value, .. } => direct(*value, visiting),
                    CheckedCallEntry::FreshOut { .. } | CheckedCallEntry::ForwardOut { .. } => None,
                }),
            CheckedExpressionKind::Draining { input }
            | CheckedExpressionKind::Hold { initial: input, .. } => direct(*input, visiting),
            CheckedExpressionKind::Flush { payload } => direct(*payload, visiting),
            CheckedExpressionKind::When { input, arms }
            | CheckedExpressionKind::While { input, arms } => direct(*input, visiting)
                .or_else(|| arms.iter().find_map(|arm| direct(*arm, visiting))),
            CheckedExpressionKind::Then { input, output } => direct(*input, visiting)
                .or_else(|| output.and_then(|output| direct(output, visiting))),
            CheckedExpressionKind::Infix { left, right, .. } => {
                direct(*left, visiting).or_else(|| direct(*right, visiting))
            }
            CheckedExpressionKind::MatchArm { output, .. } => {
                output.and_then(|output| direct(output, visiting))
            }
            CheckedExpressionKind::Block { bindings, result } => bindings
                .iter()
                .find_map(|binding| direct(binding.value, visiting))
                .or_else(|| result.and_then(|result| direct(result, visiting))),
            CheckedExpressionKind::List { items, .. }
            | CheckedExpressionKind::Bytes { items, .. }
            | CheckedExpressionKind::Set { items }
            | CheckedExpressionKind::Latest { branches: items } => {
                items.iter().find_map(|item| direct(*item, visiting))
            }
            CheckedExpressionKind::Map { entries } => {
                entries.iter().find_map(|entry| direct(*entry, visiting))
            }
            CheckedExpressionKind::MapEntry { key, value } => {
                direct(*key, visiting).or_else(|| direct(*value, visiting))
            }
            CheckedExpressionKind::TextTemplate { segments } => {
                segments.iter().find_map(|segment| match segment {
                    CheckedTextSegment::Static { .. } => None,
                    CheckedTextSegment::Dynamic { value } => direct(*value, visiting),
                })
            }
            CheckedExpressionKind::Read { .. }
            | CheckedExpressionKind::Passed { .. }
            | CheckedExpressionKind::ExternalRead { .. }
            | CheckedExpressionKind::Drain { .. }
            | CheckedExpressionKind::Text { .. }
            | CheckedExpressionKind::Number { .. }
            | CheckedExpressionKind::Bits { .. }
            | CheckedExpressionKind::BytesByte { .. }
            | CheckedExpressionKind::Absent
            | CheckedExpressionKind::Tag { .. }
            | CheckedExpressionKind::Source
            | CheckedExpressionKind::Delimiter
            | CheckedExpressionKind::Invalid { .. } => None,
        };
        visiting.remove(&current);
        result
    }

    visit(expressions, calls, root, target, &mut BTreeSet::new())
}

fn checked_hold_update_mergers(
    statements: &[CheckedStatement],
    expressions: &[CheckedExpression],
    declaration_statements: &BTreeMap<DeclId, CheckedStatementId>,
    calls: &BTreeMap<CheckedCallId, &CheckedCall>,
) -> BTreeSet<CheckedExprId> {
    let statement_by_id = statements
        .iter()
        .map(|statement| (statement.id, statement))
        .collect::<BTreeMap<_, _>>();
    let mut roots = Vec::new();
    for expression in expressions
        .iter()
        .filter(|expression| matches!(expression.kind, CheckedExpressionKind::Hold { .. }))
    {
        if let Some(statement) = expression
            .declaration
            .and_then(|declaration| declaration_statements.get(&declaration))
            .and_then(|statement| statement_by_id.get(statement))
        {
            roots.extend(checked_statement_child_values(statement, &statement_by_id));
        }
    }
    for statement in statements
        .iter()
        .filter(|statement| matches!(statement.kind, CheckedStatementKind::Hold { .. }))
    {
        roots.extend(checked_statement_child_values(statement, &statement_by_id));
    }

    let mut mergers = BTreeSet::new();
    let mut pending = roots;
    let mut visited = BTreeSet::new();
    while let Some(expression) = pending.pop() {
        if !visited.insert(expression) {
            continue;
        }
        let Some(expression) = expressions
            .get(expression.0 as usize)
            .filter(|candidate| candidate.id == expression)
        else {
            continue;
        };
        if matches!(expression.kind, CheckedExpressionKind::Hold { .. })
            || matches!(expression.kind, CheckedExpressionKind::Call { .. })
                && expression.effect.writes_state
        {
            continue;
        }
        if matches!(expression.kind, CheckedExpressionKind::Latest { .. }) {
            mergers.insert(expression.id);
        }
        pending.extend(checked_expression_children(&expression.kind, calls));
    }
    mergers
}

fn checked_statement_child_values(
    statement: &CheckedStatement,
    statements: &BTreeMap<CheckedStatementId, &CheckedStatement>,
) -> Vec<CheckedExprId> {
    let mut values = Vec::new();
    let mut pending = statement.children.iter().rev().copied().collect::<Vec<_>>();
    let mut visited = BTreeSet::new();
    while let Some(statement) = pending.pop() {
        if !visited.insert(statement) {
            continue;
        }
        let Some(statement) = statements.get(&statement) else {
            continue;
        };
        if let Some(value) = statement.value {
            values.push(value);
        } else {
            pending.extend(statement.children.iter().rev().copied());
        }
    }
    values
}

fn checked_expression_children(
    kind: &CheckedExpressionKind,
    calls: &BTreeMap<CheckedCallId, &CheckedCall>,
) -> Vec<CheckedExprId> {
    match kind {
        CheckedExpressionKind::Call { call } => calls
            .get(call)
            .into_iter()
            .flat_map(|call| &call.entries)
            .filter_map(|entry| match entry {
                CheckedCallEntry::Input { value, .. } => Some(*value),
                CheckedCallEntry::FreshOut { .. } | CheckedCallEntry::ForwardOut { .. } => None,
            })
            .collect(),
        CheckedExpressionKind::TaggedObject { fields, .. }
        | CheckedExpressionKind::Object { fields } => {
            fields.iter().map(|field| field.value).collect()
        }
        CheckedExpressionKind::Draining { input } => vec![*input],
        CheckedExpressionKind::Flush { payload } => vec![*payload],
        CheckedExpressionKind::Hold { initial, .. } => vec![*initial],
        CheckedExpressionKind::Latest { branches } => branches.clone(),
        CheckedExpressionKind::When { input, arms }
        | CheckedExpressionKind::While { input, arms } => std::iter::once(*input)
            .chain(arms.iter().copied())
            .collect(),
        CheckedExpressionKind::Then { input, output } => std::iter::once(*input)
            .chain(output.iter().copied())
            .collect(),
        CheckedExpressionKind::Infix { left, right, .. } => vec![*left, *right],
        CheckedExpressionKind::MatchArm { output, .. } => output.iter().copied().collect(),
        CheckedExpressionKind::Block { bindings, result } => bindings
            .iter()
            .map(|binding| binding.value)
            .chain(result.iter().copied())
            .collect(),
        CheckedExpressionKind::List { items, .. }
        | CheckedExpressionKind::Bytes { items, .. }
        | CheckedExpressionKind::Set { items } => items.clone(),
        CheckedExpressionKind::Map { entries } => entries.clone(),
        CheckedExpressionKind::MapEntry { key, value } => vec![*key, *value],
        CheckedExpressionKind::TextTemplate { segments } => segments
            .iter()
            .filter_map(|segment| match segment {
                CheckedTextSegment::Static { .. } => None,
                CheckedTextSegment::Dynamic { value } => Some(*value),
            })
            .collect(),
        CheckedExpressionKind::Read { .. }
        | CheckedExpressionKind::Passed { .. }
        | CheckedExpressionKind::ExternalRead { .. }
        | CheckedExpressionKind::Drain { .. }
        | CheckedExpressionKind::Text { .. }
        | CheckedExpressionKind::Number { .. }
        | CheckedExpressionKind::Bits { .. }
        | CheckedExpressionKind::BytesByte { .. }
        | CheckedExpressionKind::Absent
        | CheckedExpressionKind::Tag { .. }
        | CheckedExpressionKind::Source
        | CheckedExpressionKind::Delimiter
        | CheckedExpressionKind::Invalid { .. } => Vec::new(),
    }
}

#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
struct CheckedAuthorityOriginKey {
    /// The executable construction or call site in the current dynamic scope.
    site: CheckedExprId,
    /// The exact constructor within that site. This distinguishes two fresh
    /// authorities returned by one user call.
    constructor: CheckedExprId,
}

#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
enum CheckedAuthorityParentKind {
    MapKey,
    ListOccurrence,
}

#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
struct CheckedAuthorityParentSite {
    kind: CheckedAuthorityParentKind,
    authority: CheckedAuthorityOriginKey,
    attachment: CheckedExprId,
}

struct CheckedAuthorityAnalyzer<'a> {
    expressions: BTreeMap<CheckedExprId, &'a CheckedExpression>,
    declarations: BTreeMap<DeclId, &'a CheckedDeclaration>,
    calls: BTreeMap<CheckedCallId, &'a CheckedCall>,
    callables: BTreeMap<DeclId, &'a CheckedCallableSignature>,
    scopes: BTreeMap<LexicalScopeId, &'a CheckedScope>,
}

impl<'a> CheckedAuthorityAnalyzer<'a> {
    fn new(program: &'a CheckedProgram) -> Self {
        Self {
            expressions: program
                .expressions
                .iter()
                .map(|expression| (expression.id, expression))
                .collect(),
            declarations: program
                .declarations
                .iter()
                .map(|declaration| (declaration.id, declaration))
                .collect(),
            calls: program.calls.iter().map(|call| (call.id, call)).collect(),
            callables: program
                .callables
                .iter()
                .map(|callable| (callable.decl_id, callable))
                .collect(),
            scopes: program
                .scopes
                .iter()
                .map(|scope| (scope.id, scope))
                .collect(),
        }
    }

    fn origins(&self, expression: CheckedExprId) -> BTreeMap<CheckedAuthorityOriginKey, bool> {
        self.origins_inner(
            expression,
            &BTreeMap::new(),
            None,
            None,
            &mut BTreeSet::new(),
        )
    }

    /// Returns root collection authorities carried by one value. The boolean
    /// is true when the value borrows an authority from an owner scope rather
    /// than constructing a fresh authority at the returned site.
    fn origins_inner(
        &self,
        expression: CheckedExprId,
        substitutions: &BTreeMap<DeclId, CheckedExprId>,
        fresh_site: Option<CheckedExprId>,
        callable_scope: Option<LexicalScopeId>,
        active: &mut BTreeSet<(CheckedExprId, Option<CheckedExprId>)>,
    ) -> BTreeMap<CheckedAuthorityOriginKey, bool> {
        let Some(expression_node) = self.expressions.get(&expression).copied() else {
            return BTreeMap::new();
        };
        if !type_may_contain_collection_authority(&expression_node.flow_type.ty)
            || !active.insert((expression, fresh_site))
        {
            return BTreeMap::new();
        }

        let mut result = BTreeMap::new();
        let mut merge = |extra: BTreeMap<CheckedAuthorityOriginKey, bool>| {
            for (origin, borrowed) in extra {
                result
                    .entry(origin)
                    .and_modify(|existing| *existing |= borrowed)
                    .or_insert(borrowed);
            }
        };
        let recurse = |child,
                       substitutions: &BTreeMap<DeclId, CheckedExprId>,
                       fresh_site,
                       callable_scope,
                       active: &mut BTreeSet<_>| {
            self.origins_inner(child, substitutions, fresh_site, callable_scope, active)
        };

        match &expression_node.kind {
            CheckedExpressionKind::List { .. }
            | CheckedExpressionKind::Map { .. }
            | CheckedExpressionKind::Set { .. } => {
                result.insert(
                    CheckedAuthorityOriginKey {
                        site: fresh_site.unwrap_or(expression),
                        constructor: expression,
                    },
                    false,
                );
            }
            CheckedExpressionKind::Read { target, .. } => {
                if let Some(actual) = substitutions.get(target).copied() {
                    merge(recurse(actual, substitutions, None, None, active));
                } else if let Some(declaration) = self.declarations.get(target)
                    && let Some(value) = declaration.value
                {
                    let local_to_callable = callable_scope
                        .is_some_and(|scope| self.scope_descends_from(declaration.scope_id, scope));
                    merge(recurse(
                        value,
                        substitutions,
                        local_to_callable.then_some(fresh_site).flatten(),
                        callable_scope.filter(|_| local_to_callable),
                        active,
                    ));
                } else {
                    result.insert(
                        CheckedAuthorityOriginKey {
                            site: expression,
                            constructor: expression,
                        },
                        true,
                    );
                }
            }
            CheckedExpressionKind::Call { call } => {
                let Some(call) = self.calls.get(call).copied() else {
                    result.insert(
                        CheckedAuthorityOriginKey {
                            site: expression,
                            constructor: expression,
                        },
                        true,
                    );
                    active.remove(&(expression, fresh_site));
                    return result;
                };
                match call.function.as_str() {
                    "List/map" | "List/range" => {
                        result.insert(
                            CheckedAuthorityOriginKey {
                                site: fresh_site.unwrap_or(expression),
                                constructor: expression,
                            },
                            false,
                        );
                    }
                    "Map/upsert" | "Map/remove" | "Set/add" | "Set/remove" | "List/append"
                    | "List/filter" | "List/retain" | "List/remove" | "List/sort_by"
                    | "List/then_by" | "List/take" => {
                        if let Some(receiver) = checked_call_pipe_input(call) {
                            merge(recurse(
                                receiver,
                                substitutions,
                                fresh_site,
                                callable_scope,
                                active,
                            ));
                        }
                    }
                    "Map/get" => {
                        result.insert(
                            CheckedAuthorityOriginKey {
                                site: fresh_site.unwrap_or(expression),
                                constructor: expression,
                            },
                            true,
                        );
                    }
                    function if is_registered_render_constructor(function) => {
                        for entry in &call.entries {
                            if let CheckedCallEntry::Input { value, .. } = entry {
                                merge(recurse(
                                    *value,
                                    substitutions,
                                    fresh_site,
                                    callable_scope,
                                    active,
                                ));
                            }
                        }
                    }
                    _ => {
                        let callable = self.callables.get(&call.callable).copied();
                        if let Some(callable) =
                            callable.filter(|callable| callable.kind == CheckedCallableKind::User)
                            && let Some(output) = callable.result_expression
                        {
                            let mut nested_substitutions = substitutions.clone();
                            for entry in &call.entries {
                                if let CheckedCallEntry::Input { formal, value, .. } = entry {
                                    nested_substitutions.insert(*formal, *value);
                                }
                            }
                            merge(recurse(
                                output,
                                &nested_substitutions,
                                Some(fresh_site.unwrap_or(expression)),
                                Some(callable.scope_id),
                                active,
                            ));
                        } else {
                            result.insert(
                                CheckedAuthorityOriginKey {
                                    site: fresh_site.unwrap_or(expression),
                                    constructor: expression,
                                },
                                true,
                            );
                        }
                    }
                }
            }
            CheckedExpressionKind::TaggedObject { fields, .. }
            | CheckedExpressionKind::Object { fields } => {
                for field in fields {
                    merge(recurse(
                        field.value,
                        substitutions,
                        fresh_site,
                        callable_scope,
                        active,
                    ));
                }
            }
            CheckedExpressionKind::Latest { branches } => {
                for branch in branches {
                    merge(recurse(
                        *branch,
                        substitutions,
                        fresh_site,
                        callable_scope,
                        active,
                    ));
                }
            }
            CheckedExpressionKind::When { arms, .. }
            | CheckedExpressionKind::While { arms, .. } => {
                for arm in arms {
                    merge(recurse(
                        *arm,
                        substitutions,
                        fresh_site,
                        callable_scope,
                        active,
                    ));
                }
            }
            CheckedExpressionKind::Then { output, .. } => {
                if let Some(output) = output {
                    merge(recurse(
                        *output,
                        substitutions,
                        fresh_site,
                        callable_scope,
                        active,
                    ));
                }
            }
            CheckedExpressionKind::MatchArm { output, .. } => {
                if let Some(output) = output {
                    merge(recurse(
                        *output,
                        substitutions,
                        fresh_site,
                        callable_scope,
                        active,
                    ));
                }
            }
            CheckedExpressionKind::Block { result: output, .. } => {
                if let Some(output) = output {
                    merge(recurse(
                        *output,
                        substitutions,
                        fresh_site,
                        callable_scope,
                        active,
                    ));
                }
            }
            CheckedExpressionKind::Draining { input }
            | CheckedExpressionKind::Hold { initial: input, .. } => {
                merge(recurse(
                    *input,
                    substitutions,
                    fresh_site,
                    callable_scope,
                    active,
                ));
            }
            CheckedExpressionKind::MapEntry { value, .. } => {
                merge(recurse(
                    *value,
                    substitutions,
                    fresh_site,
                    callable_scope,
                    active,
                ));
            }
            CheckedExpressionKind::Passed { .. }
            | CheckedExpressionKind::ExternalRead { .. }
            | CheckedExpressionKind::Drain { .. } => {
                result.insert(
                    CheckedAuthorityOriginKey {
                        site: expression,
                        constructor: expression,
                    },
                    true,
                );
            }
            CheckedExpressionKind::Flush { .. }
            | CheckedExpressionKind::Infix { .. }
            | CheckedExpressionKind::TextTemplate { .. }
            | CheckedExpressionKind::Bytes { .. }
            | CheckedExpressionKind::Text { .. }
            | CheckedExpressionKind::Number { .. }
            | CheckedExpressionKind::Bits { .. }
            | CheckedExpressionKind::BytesByte { .. }
            | CheckedExpressionKind::Absent
            | CheckedExpressionKind::Tag { .. }
            | CheckedExpressionKind::Source
            | CheckedExpressionKind::Delimiter
            | CheckedExpressionKind::Invalid { .. } => {}
        }
        active.remove(&(expression, fresh_site));
        result
    }

    fn scope_descends_from(&self, mut scope: LexicalScopeId, ancestor: LexicalScopeId) -> bool {
        let mut visited = BTreeSet::new();
        while visited.insert(scope) {
            if scope == ancestor {
                return true;
            }
            let Some(parent) = self.scopes.get(&scope).and_then(|scope| scope.parent) else {
                return false;
            };
            scope = parent;
        }
        false
    }

    fn structurally_contains(&self, root: CheckedExprId, target: CheckedExprId) -> bool {
        let mut pending = vec![root];
        let mut visited = BTreeSet::new();
        while let Some(expression) = pending.pop() {
            if expression == target {
                return true;
            }
            if !visited.insert(expression) {
                continue;
            }
            let Some(expression) = self.expressions.get(&expression) else {
                continue;
            };
            pending.extend(checked_expression_children(&expression.kind, &self.calls));
        }
        false
    }
}

fn checked_call_pipe_input(call: &CheckedCall) -> Option<CheckedExprId> {
    call.entries.iter().find_map(|entry| match entry {
        CheckedCallEntry::Input {
            value,
            from_pipe: true,
            ..
        } => Some(*value),
        CheckedCallEntry::Input {
            from_pipe: false, ..
        }
        | CheckedCallEntry::FreshOut { .. }
        | CheckedCallEntry::ForwardOut { .. } => None,
    })
}

fn checked_call_named_input(call: &CheckedCall, name: &str) -> Option<CheckedExprId> {
    call.entries.iter().find_map(|entry| match entry {
        CheckedCallEntry::Input {
            name: candidate,
            value,
            ..
        } if candidate == name => Some(*value),
        CheckedCallEntry::Input { .. }
        | CheckedCallEntry::FreshOut { .. }
        | CheckedCallEntry::ForwardOut { .. } => None,
    })
}

fn validate_checked_collection_authority_attachments(
    program: &CheckedProgram,
) -> Vec<TypeDiagnostic> {
    let analyzer = CheckedAuthorityAnalyzer::new(program);
    let mut diagnostics = Vec::new();
    let mut seen_diagnostics = BTreeSet::<(CheckedExprId, String)>::new();
    let mut parents =
        BTreeMap::<CheckedAuthorityOriginKey, BTreeSet<CheckedAuthorityParentSite>>::new();
    let mut graph =
        BTreeMap::<CheckedAuthorityOriginKey, BTreeSet<CheckedAuthorityOriginKey>>::new();

    let mut attach = |root: CheckedExprId,
                      parent: CheckedAuthorityParentSite,
                      diagnostics: &mut Vec<TypeDiagnostic>| {
        let origins = analyzer.origins(root);
        for (origin, borrowed) in origins {
            let message = if origin == parent.authority
                || checked_authority_graph_reaches(&graph, parent.authority, origin)
            {
                Some(
                    "nested collection authority attachment forms an ownership cycle; construct nested LIST, SET, or MAP authorities only inside an acyclic parent value"
                        .to_owned(),
                )
            } else if borrowed {
                Some(
                    "nested collection authority escapes its owner or is reattached from an existing owner; construct a fresh LIST, SET, or MAP authority inside this parent value"
                        .to_owned(),
                )
            } else if !analyzer.structurally_contains(root, origin.site) {
                Some(
                    "collection authority is attached beneath a second parent or beyond its owner lifetime; construct it inside this MAP value or LIST occurrence"
                        .to_owned(),
                )
            } else {
                None
            };
            if let Some(message) = message
                && seen_diagnostics.insert((root, message.clone()))
            {
                diagnostics.push(checked_authority_diagnostic(program, root, message));
            }

            let origin_parents = parents.entry(origin).or_default();
            origin_parents.insert(parent);
            if origin_parents.len() > 1 {
                let message =
                    "collection authority has more than one structural parent; each nested authority must belong to exactly one MAP key or LIST occurrence"
                        .to_owned();
                if seen_diagnostics.insert((root, message.clone())) {
                    diagnostics.push(checked_authority_diagnostic(program, root, message));
                }
            }
            graph.entry(origin).or_default().insert(parent.authority);
        }
    };

    for expression in &program.expressions {
        match &expression.kind {
            CheckedExpressionKind::Map { entries } => {
                let parent = CheckedAuthorityOriginKey {
                    site: expression.id,
                    constructor: expression.id,
                };
                for entry in entries {
                    let Some(CheckedExpression {
                        kind: CheckedExpressionKind::MapEntry { value, .. },
                        ..
                    }) = analyzer.expressions.get(entry).copied()
                    else {
                        continue;
                    };
                    attach(
                        *value,
                        CheckedAuthorityParentSite {
                            kind: CheckedAuthorityParentKind::MapKey,
                            authority: parent,
                            attachment: *entry,
                        },
                        &mut diagnostics,
                    );
                }
            }
            CheckedExpressionKind::List { items, .. } => {
                let parent = CheckedAuthorityOriginKey {
                    site: expression.id,
                    constructor: expression.id,
                };
                for item in items {
                    attach(
                        *item,
                        CheckedAuthorityParentSite {
                            kind: CheckedAuthorityParentKind::ListOccurrence,
                            authority: parent,
                            attachment: *item,
                        },
                        &mut diagnostics,
                    );
                }
            }
            CheckedExpressionKind::Call { call } => {
                let Some(call) = analyzer.calls.get(call).copied() else {
                    continue;
                };
                let Some(receiver) = checked_call_pipe_input(call) else {
                    continue;
                };
                let parent_origins = analyzer.origins(receiver);
                let attachment = match call.function.as_str() {
                    "Map/upsert" => checked_call_named_input(call, "entry")
                        .map(|root| (CheckedAuthorityParentKind::MapKey, root)),
                    "List/append" => checked_call_named_input(call, "item")
                        .map(|root| (CheckedAuthorityParentKind::ListOccurrence, root)),
                    _ => None,
                };
                let Some((kind, root)) = attachment else {
                    continue;
                };
                for authority in parent_origins.keys().copied() {
                    attach(
                        root,
                        CheckedAuthorityParentSite {
                            kind,
                            authority,
                            attachment: expression.id,
                        },
                        &mut diagnostics,
                    );
                }
            }
            _ => {}
        }
    }

    diagnostics
}

fn checked_authority_graph_reaches(
    graph: &BTreeMap<CheckedAuthorityOriginKey, BTreeSet<CheckedAuthorityOriginKey>>,
    root: CheckedAuthorityOriginKey,
    target: CheckedAuthorityOriginKey,
) -> bool {
    let mut pending = vec![root];
    let mut visited = BTreeSet::new();
    while let Some(origin) = pending.pop() {
        if origin == target {
            return true;
        }
        if visited.insert(origin)
            && let Some(parents) = graph.get(&origin)
        {
            pending.extend(parents.iter().copied());
        }
    }
    false
}

fn checked_authority_diagnostic(
    program: &CheckedProgram,
    expression: CheckedExprId,
    message: String,
) -> TypeDiagnostic {
    let span = program
        .expressions
        .get(expression.0 as usize)
        .filter(|candidate| candidate.id == expression)
        .map(|expression| expression.span)
        .unwrap_or_default();
    TypeDiagnostic {
        severity: DiagnosticSeverity::Error,
        line: span.line,
        start: span.start,
        end: span.end,
        message,
    }
}

fn source_path_part_candidates(parts: &[String]) -> Vec<Vec<String>> {
    let mut candidates = Vec::new();
    for (strip_event, strip_events) in [(false, false), (true, false), (false, true), (true, true)]
    {
        let candidate = parts
            .iter()
            .filter(|part| {
                part.as_str() != "PASSED"
                    && (!strip_event || part.as_str() != "event")
                    && (!strip_events || part.as_str() != "events")
            })
            .cloned()
            .collect::<Vec<_>>();
        if !candidates.contains(&candidate) {
            candidates.push(candidate);
        }
    }
    candidates
}

fn source_payload_access_for_suffix(suffix: &str) -> SourcePayloadAccess {
    let suffix = suffix
        .strip_prefix("event.")
        .or_else(|| suffix.strip_prefix("events."))
        .unwrap_or(suffix);
    match suffix {
        "change.text" => SourcePayloadAccess::Field("text".to_owned()),
        "change.bytes" => SourcePayloadAccess::Field("bytes".to_owned()),
        "key_down.key" => SourcePayloadAccess::Field("key".to_owned()),
        "press" | "click" | "double_click" | "blur" | "change" | "key_down" => {
            SourcePayloadAccess::Field(suffix.to_owned())
        }
        field if !field.contains('.') => SourcePayloadAccess::Field(field.to_owned()),
        _ => SourcePayloadAccess::UnknownField(suffix.to_owned()),
    }
}

fn simple_record_shape(fields: &[AstRecordField], expressions: &[AstExpr]) -> ObjectShape {
    let mut shape_fields = BTreeMap::new();
    let mut field_order = Vec::new();
    for field in fields {
        let ty = expressions
            .get(field.value)
            .map(|expr| simple_expr_type(expr, expressions))
            .unwrap_or_else(open_object_type);
        if field.spread {
            if let Type::Object(shape) = ty {
                merge_shape_override(&mut shape_fields, &mut field_order, &shape);
            }
            continue;
        }
        insert_shape_field_override(&mut shape_fields, &mut field_order, field.name.clone(), ty);
    }
    ObjectShape {
        fields: shape_fields,
        field_order,
        open: false,
    }
}

fn source_payload_field_type(field: &str) -> Type {
    match field {
        "press" | "click" | "double_click" | "blur" | "change" | "key_down" => {
            exact_empty_object_type()
        }
        "bytes" => Type::Bytes(BytesType::Dynamic),
        _ => Type::Text,
    }
}

fn declared_source_payload_field_type(
    source_lookup: &SourcePayloadPathLookup,
    source_payload_types: &BTreeMap<String, Type>,
    parts: &[String],
    field: &str,
) -> Option<Type> {
    source_lookup
        .source_paths_for_parts(parts)
        .into_iter()
        .find_map(|source_path| {
            let Type::Object(shape) =
                source_payload_type_for_path(source_payload_types, &source_path)?
            else {
                return None;
            };
            shape.fields.get(field).cloned()
        })
}

fn source_payload_type_for_path(
    source_payload_types: &BTreeMap<String, Type>,
    path: &str,
) -> Option<Type> {
    source_payload_types.get(path).cloned().or_else(|| {
        source_payload_types
            .iter()
            .find(|(source_path, _)| {
                let relative = source_path.strip_prefix("store.").unwrap_or(source_path);
                *source_path == path
                    || source_path.ends_with(&format!(".{path}"))
                    || relative == path
                    || relative.ends_with(&format!(".{path}"))
            })
            .map(|(_, ty)| ty.clone())
    })
}

fn source_payload_shape_table(
    program: &ParsedProgram,
    source_sites: &[SyntaxSourceSite],
    source_lookup: &SourcePayloadPathLookup,
    host_ports: &HostPortSyntaxTable,
) -> Vec<SourcePayloadSyntaxShapeEntry> {
    let source_paths = source_sites
        .iter()
        .map(|source| source.path.clone())
        .collect::<BTreeSet<_>>();
    let mut fields_by_source = source_paths
        .iter()
        .map(|source_path| (source_path.clone(), BTreeMap::new()))
        .collect::<BTreeMap<String, BTreeMap<String, Type>>>();
    for expr in &program.expressions {
        let AstExprKind::Path(parts) = &expr.kind else {
            continue;
        };
        let Some(SourcePayloadAccess::Field(field)) = source_lookup.access_for_parts(parts) else {
            continue;
        };
        for source_path in source_lookup.source_paths_for_parts(parts) {
            if let Some(fields) = fields_by_source.get_mut(&source_path) {
                fields.insert(field.clone(), source_payload_field_type(&field));
            }
        }
    }
    collect_contextual_source_payload_list_types(program, source_lookup, &mut fields_by_source);
    collect_payload_pattern_fields(
        &program.ast.statements,
        &program.expressions,
        source_lookup,
        &mut fields_by_source,
    );
    collect_payload_hold_update_types(
        &program.ast.statements,
        &program.ast.statements,
        &program.expressions,
        source_lookup,
        &mut fields_by_source,
    );
    for expr in &program.expressions {
        let AstExprKind::Call { function, args, .. } = &expr.kind else {
            continue;
        };
        let Some(signature) = host_effect_signature(function) else {
            continue;
        };
        for (argument_name, argument_value) in named_call_argument_exprs(program, expr.id, args) {
            let Some(expected_field) = signature
                .intent_fields
                .iter()
                .find(|field| field.name == argument_name)
            else {
                continue;
            };
            let expected_type = &expected_field.ty;
            let Some(AstExpr {
                kind: AstExprKind::Path(parts),
                ..
            }) = program.expressions.get(argument_value)
            else {
                continue;
            };
            let Some(SourcePayloadAccess::Field(payload_field)) =
                source_lookup.access_for_parts(parts)
            else {
                continue;
            };
            for source_path in source_lookup.source_paths_for_parts(parts) {
                if let Some(fields) = fields_by_source.get_mut(&source_path) {
                    fields.insert(payload_field.clone(), expected_type.clone());
                }
            }
        }
    }
    for (source_path, host_fields) in host_port_payload_types(host_ports) {
        let Some(fields) = fields_by_source.get_mut(&source_path) else {
            continue;
        };
        for (name, ty) in host_fields {
            fields.insert(name, ty);
        }
    }
    source_sites
        .iter()
        .map(|source| {
            let fields = fields_by_source
                .get(&source.path)
                .cloned()
                .unwrap_or_default()
                .into_iter()
                .map(|(name, ty)| SourcePayloadShapeField { name, ty })
                .collect::<Vec<_>>();
            let payload_type = Type::object(ObjectShape::from_ordered_fields(
                fields
                    .iter()
                    .map(|field| (field.name.clone(), field.ty.clone())),
                false,
            ));
            SourcePayloadSyntaxShapeEntry {
                statement: source.statement,
                source_path: source.path.clone(),
                payload_type,
                fields,
            }
        })
        .collect()
}

fn collect_contextual_source_payload_list_types(
    program: &ParsedProgram,
    source_lookup: &SourcePayloadPathLookup,
    fields_by_source: &mut BTreeMap<String, BTreeMap<String, Type>>,
) {
    let declarations = declaration_expression_index(program);
    let mut when_expressions_by_selector = HashMap::<usize, Vec<usize>>::new();
    for expression in &program.expressions {
        let AstExprKind::When { input, .. } = &expression.kind else {
            continue;
        };
        let selector = pipeline_source_expr_id(
            &program.ast.statements,
            expression.id,
            *input,
            &program.expressions,
        );
        when_expressions_by_selector
            .entry(selector)
            .or_default()
            .push(expression.id);
    }
    let mut requirements = BTreeMap::<(String, String), Type>::new();

    for expression in &program.expressions {
        let (function, args, input) = match &expression.kind {
            AstExprKind::Call { function, args, .. } => {
                let Some(input) = named_arg_expr(args, "list") else {
                    continue;
                };
                (function.as_str(), args.as_slice(), input)
            }
            AstExprKind::Pipe {
                input, op, args, ..
            } => (
                op.as_str(),
                args.as_slice(),
                pipeline_source_expr_id(
                    &program.ast.statements,
                    expression.id,
                    *input,
                    &program.expressions,
                ),
            ),
            _ => continue,
        };
        let Some(body_parameter) = contextual_body_parameter_name(function) else {
            continue;
        };
        let Some(binding) = args
            .iter()
            .find(|argument| argument.is_bare_binding())
            .and_then(|argument| program.expressions.get(argument.value))
            .and_then(expr_single_name)
        else {
            continue;
        };
        let Some(body) = named_arg_expr(args, body_parameter) else {
            continue;
        };

        let mut row_fields = BTreeMap::<Vec<String>, Type>::new();
        collect_contextual_binding_field_requirements(
            body,
            binding,
            None,
            &program.expressions,
            &mut row_fields,
        );
        if function == "List/find" {
            collect_find_result_field_requirements(
                expression.id,
                program,
                &when_expressions_by_selector,
                &mut row_fields,
            );
        }
        if row_fields.is_empty() {
            continue;
        }

        let row_type = contextual_binding_row_type(&row_fields);
        let list_type = Type::List(Type::shared(row_type));
        for origin in source_payload_list_field_origins(
            input,
            program,
            source_lookup,
            &declarations,
            &mut BTreeSet::new(),
        ) {
            requirements
                .entry(origin)
                .and_modify(|existing| {
                    *existing = merge_source_payload_structural_requirement(existing, &list_type);
                })
                .or_insert_with(|| list_type.clone());
        }
    }

    for ((source_path, field), requirement) in requirements {
        if let Some(fields) = fields_by_source.get_mut(&source_path) {
            fields.insert(field, requirement);
        }
    }
}

fn collect_find_result_field_requirements(
    find_expression: usize,
    program: &ParsedProgram,
    when_expressions_by_selector: &HashMap<usize, Vec<usize>>,
    requirements: &mut BTreeMap<Vec<String>, Type>,
) {
    for expression in when_expressions_by_selector
        .get(&find_expression)
        .into_iter()
        .flatten()
        .filter_map(|expression| program.expressions.get(*expression))
    {
        for (pattern, output) in when_arms(expression.id, &program.expressions) {
            let AstMatchPattern::Tag { name, fields } = pattern else {
                continue;
            };
            if name != "Found" {
                continue;
            }
            for binding in fields {
                collect_contextual_binding_field_requirements(
                    output,
                    &binding,
                    None,
                    &program.expressions,
                    requirements,
                );
            }
        }
    }
}

fn collect_contextual_binding_field_requirements(
    expr_id: usize,
    binding: &str,
    expected: Option<Type>,
    expressions: &[AstExpr],
    requirements: &mut BTreeMap<Vec<String>, Type>,
) {
    let Some(expression) = expressions.get(expr_id) else {
        return;
    };
    let add_path = |path: &[String],
                    expected: Option<Type>,
                    requirements: &mut BTreeMap<Vec<String>, Type>| {
        if path.is_empty() {
            return;
        }
        let ty = expected
            .filter(|ty| !is_value_placeholder_type(ty))
            .unwrap_or(Type::Text);
        requirements
            .entry(path.to_vec())
            .and_modify(|existing| {
                *existing = merge_source_payload_structural_requirement(existing, &ty);
            })
            .or_insert(ty);
    };

    match &expression.kind {
        AstExprKind::Path(parts) if parts.first().is_some_and(|root| root == binding) => {
            add_path(&parts[1..], expected, requirements);
        }
        AstExprKind::Drain { path } => {
            let parts = drain_path_parts(path);
            if parts.first().is_some_and(|root| root == binding) {
                add_path(&parts[1..], expected, requirements);
            }
        }
        AstExprKind::Infix { left, op, right } => {
            let (left_expected, right_expected) = if infix_requires_number_operands(op) {
                (Some(Type::Number), Some(Type::Number))
            } else {
                (
                    expressions
                        .get(*right)
                        .map(|expression| simple_expr_type(expression, expressions))
                        .filter(type_is_recursively_closed),
                    expressions
                        .get(*left)
                        .map(|expression| simple_expr_type(expression, expressions))
                        .filter(type_is_recursively_closed),
                )
            };
            collect_contextual_binding_field_requirements(
                *left,
                binding,
                left_expected,
                expressions,
                requirements,
            );
            collect_contextual_binding_field_requirements(
                *right,
                binding,
                right_expected,
                expressions,
                requirements,
            );
        }
        AstExprKind::Call { function, args, .. }
        | AstExprKind::Pipe {
            op: function, args, ..
        } => {
            let shadows_binding = args.iter().any(|argument| {
                argument.is_bare_binding()
                    && expressions
                        .get(argument.value)
                        .and_then(expr_single_name)
                        .is_some_and(|name| name == binding)
            });
            if let AstExprKind::Pipe { input, .. } = &expression.kind {
                collect_contextual_binding_field_requirements(
                    expression.linked_input.unwrap_or(*input),
                    binding,
                    pipe_input_expected_type(function),
                    expressions,
                    requirements,
                );
            }
            for argument in args {
                if argument.is_bare_binding()
                    || (shadows_binding
                        && argument.named_name() == contextual_body_parameter_name(function))
                {
                    continue;
                }
                collect_contextual_binding_field_requirements(
                    argument.value,
                    binding,
                    builtin_argument_expected_type(
                        function,
                        argument.named_name(),
                        matches!(expression.kind, AstExprKind::Pipe { .. }),
                    ),
                    expressions,
                    requirements,
                );
            }
        }
        AstExprKind::Hold { initial, .. } | AstExprKind::Draining { input: initial } => {
            collect_contextual_binding_field_requirements(
                expression.linked_input.unwrap_or(*initial),
                binding,
                expected,
                expressions,
                requirements,
            );
        }
        AstExprKind::Then { input, output } => {
            collect_contextual_binding_field_requirements(
                expression.linked_input.unwrap_or(*input),
                binding,
                None,
                expressions,
                requirements,
            );
            if let Some(output) = output {
                collect_contextual_binding_field_requirements(
                    *output,
                    binding,
                    expected,
                    expressions,
                    requirements,
                );
            }
        }
        AstExprKind::When { input, arms } => {
            collect_contextual_binding_field_requirements(
                expression.linked_input.unwrap_or(*input),
                binding,
                None,
                expressions,
                requirements,
            );
            for arm in arms {
                collect_contextual_binding_field_requirements(
                    *arm,
                    binding,
                    expected.clone(),
                    expressions,
                    requirements,
                );
            }
        }
        AstExprKind::MatchArm {
            output: Some(output),
            ..
        } => collect_contextual_binding_field_requirements(
            *output,
            binding,
            expected,
            expressions,
            requirements,
        ),
        AstExprKind::Block { bindings, result } => {
            for local in bindings {
                collect_contextual_binding_field_requirements(
                    local.value,
                    binding,
                    None,
                    expressions,
                    requirements,
                );
            }
            if let Some(result) = result {
                collect_contextual_binding_field_requirements(
                    *result,
                    binding,
                    expected,
                    expressions,
                    requirements,
                );
            }
        }
        AstExprKind::Latest { branches } => {
            for branch in branches {
                collect_contextual_binding_field_requirements(
                    *branch,
                    binding,
                    expected.clone(),
                    expressions,
                    requirements,
                );
            }
        }
        AstExprKind::Object(fields) | AstExprKind::TaggedObject { fields, .. } => {
            let expected_fields = match expected.as_ref() {
                Some(Type::Object(shape)) => Some(&shape.fields),
                _ => None,
            };
            for field in fields {
                collect_contextual_binding_field_requirements(
                    field.value,
                    binding,
                    expected_fields
                        .and_then(|fields| fields.get(&field.name))
                        .cloned(),
                    expressions,
                    requirements,
                );
            }
        }
        AstExprKind::ListLiteral { items, .. }
        | AstExprKind::BytesLiteral { items, .. }
        | AstExprKind::SetLiteral { items } => {
            let item_expected = match expected.as_ref() {
                Some(Type::List(item)) | Some(Type::Set(item)) => Some((**item).clone()),
                _ => None,
            };
            for item in items {
                collect_contextual_binding_field_requirements(
                    *item,
                    binding,
                    item_expected.clone(),
                    expressions,
                    requirements,
                );
            }
        }
        AstExprKind::MapLiteral { entries } => {
            for entry in entries {
                collect_contextual_binding_field_requirements(
                    *entry,
                    binding,
                    None,
                    expressions,
                    requirements,
                );
            }
        }
        AstExprKind::MapEntry { key, value } => {
            collect_contextual_binding_field_requirements(
                *key,
                binding,
                None,
                expressions,
                requirements,
            );
            collect_contextual_binding_field_requirements(
                *value,
                binding,
                None,
                expressions,
                requirements,
            );
        }
        AstExprKind::Arrow { left, output, .. } => {
            collect_contextual_binding_field_requirements(
                *left,
                binding,
                None,
                expressions,
                requirements,
            );
            if let Some(output) = output {
                collect_contextual_binding_field_requirements(
                    *output,
                    binding,
                    expected,
                    expressions,
                    requirements,
                );
            }
        }
        AstExprKind::TextTemplate { segments } => {
            for value in segments.iter().filter_map(|segment| match segment {
                AstTextSegment::Static { .. } => None,
                AstTextSegment::Dynamic { value } => Some(*value),
            }) {
                collect_contextual_binding_field_requirements(
                    value,
                    binding,
                    Some(Type::Text),
                    expressions,
                    requirements,
                );
            }
        }
        AstExprKind::Flush {
            payload: Some(payload),
        } => collect_contextual_binding_field_requirements(
            *payload,
            binding,
            None,
            expressions,
            requirements,
        ),
        AstExprKind::Identifier(_)
        | AstExprKind::Path(_)
        | AstExprKind::StringLiteral(_)
        | AstExprKind::TextLiteral(_)
        | AstExprKind::Number(_)
        | AstExprKind::BitsLiteral { .. }
        | AstExprKind::ByteLiteral { .. }
        | AstExprKind::Tag(_)
        | AstExprKind::Source
        | AstExprKind::Delimiter
        | AstExprKind::Unknown(_)
        | AstExprKind::Flush { payload: None }
        | AstExprKind::MatchArm { output: None, .. } => {}
    }
}

fn contextual_binding_row_type(requirements: &BTreeMap<Vec<String>, Type>) -> Type {
    let mut shape = ObjectShape {
        fields: BTreeMap::new(),
        field_order: Vec::new(),
        open: false,
    };
    for (path, ty) in requirements {
        insert_source_payload_requirement_path(&mut shape, path, ty);
    }
    Type::object(shape)
}

fn insert_source_payload_requirement_path(shape: &mut ObjectShape, path: &[String], ty: &Type) {
    let Some((field, rest)) = path.split_first() else {
        return;
    };
    if !shape.fields.contains_key(field) {
        shape.field_order.push(field.clone());
    }
    if rest.is_empty() {
        shape
            .fields
            .entry(field.clone())
            .and_modify(|existing| {
                *existing = merge_source_payload_structural_requirement(existing, ty);
            })
            .or_insert_with(|| ty.clone());
        return;
    }
    let entry = shape.fields.entry(field.clone()).or_insert_with(|| {
        Type::object(ObjectShape {
            fields: BTreeMap::new(),
            field_order: Vec::new(),
            open: false,
        })
    });
    if !matches!(entry, Type::Object(_)) {
        *entry = Type::object(ObjectShape {
            fields: BTreeMap::new(),
            field_order: Vec::new(),
            open: false,
        });
    }
    let Type::Object(child) = entry else {
        unreachable!("source payload path is a structural object")
    };
    let mut child = child.as_ref().clone();
    insert_source_payload_requirement_path(&mut child, rest, ty);
    *entry = Type::object(child);
}

fn merge_source_payload_structural_requirement(left: &Type, right: &Type) -> Type {
    match (left, right) {
        (Type::List(left), Type::List(right)) => Type::List(Type::shared(
            merge_source_payload_structural_requirement(left, right),
        )),
        (Type::Object(left), Type::Object(right)) => {
            let mut fields = left.fields.clone();
            for (field, ty) in &right.fields {
                fields
                    .entry(field.clone())
                    .and_modify(|existing| {
                        *existing = merge_source_payload_structural_requirement(existing, ty);
                    })
                    .or_insert_with(|| ty.clone());
            }
            Type::object(ObjectShape {
                fields,
                field_order: object_field_order_for_widened_shapes(left, right),
                open: left.open || right.open,
            })
        }
        _ if left == right => left.clone(),
        _ => widen_structural_type(left, right),
    }
}

fn source_payload_list_field_origins(
    expr_id: usize,
    program: &ParsedProgram,
    source_lookup: &SourcePayloadPathLookup,
    declarations: &DeclarationExprIndex,
    visited: &mut BTreeSet<usize>,
) -> Vec<(String, String)> {
    if !visited.insert(expr_id) {
        return Vec::new();
    }
    let Some(expression) = program.expressions.get(expr_id) else {
        return Vec::new();
    };
    let read_parts = match &expression.kind {
        AstExprKind::Identifier(name) => Some(vec![name.clone()]),
        AstExprKind::Path(parts) => Some(parts.clone()),
        AstExprKind::Drain { path } => Some(drain_path_parts(path)),
        _ => None,
    };
    if let Some(parts) = read_parts {
        if let Some(SourcePayloadAccess::Field(field)) = source_lookup.access_for_parts(&parts) {
            return source_lookup
                .source_paths_for_parts(&parts)
                .into_iter()
                .map(|source_path| (source_path, field.clone()))
                .collect();
        }
        if let Some(value) = declaration_expr_for_path(declarations, &parts.join(".")) {
            return source_payload_list_field_origins(
                value,
                program,
                source_lookup,
                declarations,
                visited,
            );
        }
        return Vec::new();
    }

    match &expression.kind {
        AstExprKind::Pipe { input, op, .. }
            if matches!(
                op.as_str(),
                "List/filter" | "List/retain" | "List/remove" | "HOLD"
            ) =>
        {
            source_payload_list_field_origins(
                pipeline_source_expr_id(
                    &program.ast.statements,
                    expression.id,
                    *input,
                    &program.expressions,
                ),
                program,
                source_lookup,
                declarations,
                visited,
            )
        }
        AstExprKind::Hold { initial, .. } | AstExprKind::Draining { input: initial } => {
            source_payload_list_field_origins(
                expression.linked_input.unwrap_or(*initial),
                program,
                source_lookup,
                declarations,
                visited,
            )
        }
        AstExprKind::Block {
            result: Some(result),
            ..
        }
        | AstExprKind::Then {
            output: Some(result),
            ..
        }
        | AstExprKind::MatchArm {
            output: Some(result),
            ..
        } => source_payload_list_field_origins(
            *result,
            program,
            source_lookup,
            declarations,
            visited,
        ),
        AstExprKind::Latest { branches } => branches
            .iter()
            .flat_map(|branch| {
                source_payload_list_field_origins(
                    *branch,
                    program,
                    source_lookup,
                    declarations,
                    visited,
                )
            })
            .collect(),
        _ => Vec::new(),
    }
}

fn host_port_payload_types(
    host_ports: &HostPortSyntaxTable,
) -> BTreeMap<String, BTreeMap<String, Type>> {
    let mut payloads = BTreeMap::new();
    if let Some(http) = &host_ports.http {
        payloads.insert(http.request_source.clone(), http_request_payload_fields());
        if let Some(disconnect) = &http.disconnect_source {
            payloads.insert(
                disconnect.clone(),
                BTreeMap::from([
                    ("peer".to_owned(), Type::Text),
                    ("reason".to_owned(), Type::Text),
                ]),
            );
        }
    }
    if let Some(websocket) = &host_ports.websocket {
        payloads.insert(
            websocket.open_source.clone(),
            BTreeMap::from([
                ("path".to_owned(), Type::Text),
                (
                    "path_segments".to_owned(),
                    Type::List(Type::shared(Type::Text)),
                ),
                ("query".to_owned(), named_text_pairs_type()),
                ("headers".to_owned(), named_text_pairs_type()),
                ("cookies".to_owned(), named_text_pairs_type()),
                ("peer".to_owned(), Type::Text),
                ("protocols".to_owned(), Type::List(Type::shared(Type::Text))),
            ]),
        );
        payloads.insert(
            websocket.message_source.clone(),
            BTreeMap::from([
                (
                    "kind".to_owned(),
                    Type::VariantSet(
                        vec![
                            Variant::Tag("TextMessage".to_owned()),
                            Variant::Tag("BinaryMessage".to_owned()),
                        ]
                        .into(),
                    ),
                ),
                ("text".to_owned(), Type::Text),
                ("bytes".to_owned(), Type::Bytes(BytesType::Dynamic)),
            ]),
        );
        payloads.insert(
            websocket.close_source.clone(),
            BTreeMap::from([
                ("code".to_owned(), Type::Number),
                ("reason".to_owned(), Type::Text),
                ("clean".to_owned(), true_false_type()),
            ]),
        );
        payloads.insert(
            websocket.error_source.clone(),
            BTreeMap::from([
                ("code".to_owned(), Type::Text),
                ("message".to_owned(), Type::Text),
                ("retryable".to_owned(), true_false_type()),
            ]),
        );
    }
    payloads
}

fn http_request_payload_fields() -> BTreeMap<String, Type> {
    BTreeMap::from([
        ("method".to_owned(), Type::Text),
        ("scheme".to_owned(), Type::Text),
        ("path".to_owned(), Type::Text),
        (
            "path_segments".to_owned(),
            Type::List(Type::shared(Type::Text)),
        ),
        ("query".to_owned(), named_text_pairs_type()),
        ("headers".to_owned(), named_text_pairs_type()),
        ("cookies".to_owned(), named_text_pairs_type()),
        ("body".to_owned(), Type::Bytes(BytesType::Dynamic)),
        ("peer".to_owned(), Type::Text),
        ("deadline_ms".to_owned(), Type::Number),
    ])
}

fn named_text_pairs_type() -> Type {
    Type::List(Type::shared(Type::object(
        ObjectShape::from_ordered_fields(
            [
                ("name".to_owned(), Type::Text),
                ("value".to_owned(), Type::Text),
            ],
            false,
        ),
    )))
}

fn type_hint_table(
    program: &ParsedProgram,
    expr_type_table: &ExprTypeTable,
    function_type_table: &FunctionTypeTable,
    render_slot_table: &RenderSlotTable,
    source_payload_shape_table: &[SourcePayloadSyntaxShapeEntry],
    name_bindings: &BTreeMap<String, Type>,
) -> TypeHintTable {
    let source_index = TypeHintSourceIndex::new(&program.source);
    let expr_types = TypeHintExprIndex::new(expr_type_table, program.expressions.len());
    let metadata = TypeHintMetadataIndex::new(
        &program.ast.statements,
        function_type_table,
        source_payload_shape_table,
    );
    let mut entries = Vec::new();
    for expr in &program.expressions {
        let Some(ty) = expr_types.get(&expr.id) else {
            continue;
        };
        if !expr_kind_gets_type_hint(&expr.kind) {
            continue;
        }
        let category = type_hint_category_for_expr(&expr.kind);
        entries.push(type_hint_entry_for_range(
            program,
            &source_index,
            Some(expr.id),
            expr.line,
            expr.start,
            expr.end,
            category,
            ty,
        ));
        collect_call_argument_type_hints(program, &source_index, expr, &expr_types, &mut entries);
    }
    let mut statement_hint_types = BTreeMap::new();
    collect_statement_type_hints(
        program,
        &source_index,
        &program.ast.statements,
        &expr_types,
        &metadata,
        name_bindings,
        &mut statement_hint_types,
        &mut entries,
    );
    for slot in &render_slot_table.slots {
        let Some(statement) = metadata.statements.get(&slot.slot_statement_id).copied() else {
            continue;
        };
        entries.push(type_hint_entry_for_range(
            program,
            &source_index,
            slot.value_expr_id,
            statement.line,
            statement.start,
            statement.end,
            "render_slot",
            &slot.actual_type,
        ));
    }
    entries.sort_by_key(|entry| (entry.line, entry.anchor_column, entry.start, entry.end));
    entries.dedup_by(|left, right| {
        left.line == right.line
            && left.start == right.start
            && left.end == right.end
            && left.category == right.category
            && left.compact_label == right.compact_label
    });
    TypeHintTable { entries }
}

/// Borrowed dense projection over the already-owned expression table. Hint
/// generation used to deep-clone every checked type into a second BTreeMap
/// before emitting its first hint.
struct TypeHintExprIndex<'a> {
    entries: Vec<Option<&'a Type>>,
}

impl<'a> TypeHintExprIndex<'a> {
    fn new(table: &'a ExprTypeTable, expression_count: usize) -> Self {
        let mut entries = vec![None; expression_count];
        for entry in &table.entries {
            if let Some(slot) = entries.get_mut(entry.expr_id) {
                *slot = Some(&entry.flow_type.ty);
            }
        }
        Self { entries }
    }

    fn get(&self, expression: &usize) -> Option<&'a Type> {
        self.entries.get(*expression).copied().flatten()
    }
}

struct TypeHintMetadataIndex<'a> {
    statements: BTreeMap<usize, &'a AstStatement>,
    functions: BTreeMap<&'a str, &'a FunctionTypeEntry>,
    source_payloads: BTreeMap<usize, &'a SourcePayloadSyntaxShapeEntry>,
}

impl<'a> TypeHintMetadataIndex<'a> {
    fn new(
        statements: &'a [AstStatement],
        functions: &'a FunctionTypeTable,
        source_payloads: &'a [SourcePayloadSyntaxShapeEntry],
    ) -> Self {
        fn index_statements<'a>(
            statements: &'a [AstStatement],
            index: &mut BTreeMap<usize, &'a AstStatement>,
        ) {
            for statement in statements {
                index.entry(statement.id).or_insert(statement);
                index_statements(&statement.children, index);
            }
        }
        let mut statement_index = BTreeMap::new();
        index_statements(statements, &mut statement_index);
        let mut function_index = BTreeMap::new();
        for function in &functions.entries {
            function_index
                .entry(function.name.as_str())
                .or_insert(function);
        }
        let mut source_index = BTreeMap::new();
        for source in source_payloads {
            source_index.entry(source.statement).or_insert(source);
        }
        Self {
            statements: statement_index,
            functions: function_index,
            source_payloads: source_index,
        }
    }

    fn source_payload_type(&self, statement: usize) -> Option<Type> {
        self.source_payloads
            .get(&statement)
            .map(|entry| entry.payload_type.clone())
    }

    fn source_statement_value_type(&self, statement: &AstStatement) -> Type {
        let payload = self
            .source_payload_type(statement.id)
            .unwrap_or_else(exact_empty_object_type);
        match &statement.kind {
            AstStatementKind::Source {
                event: Some(event), ..
            } => Type::object(ObjectShape::from_ordered_fields(
                [(event.clone(), payload)],
                false,
            )),
            _ => payload,
        }
    }
}

/// One immutable source index shared by the entire editor-hint projection.
/// Hint construction used to rescan from byte zero for every entry, making a
/// large file's otherwise linear projection quadratic in its line count.
struct TypeHintSourceIndex<'a> {
    source: &'a str,
    line_starts: Vec<usize>,
}

impl<'a> TypeHintSourceIndex<'a> {
    fn new(source: &'a str) -> Self {
        let mut line_starts = Vec::with_capacity(source.lines().count().saturating_add(1));
        line_starts.push(0);
        for (index, byte) in source.bytes().enumerate() {
            if byte == b'\n' {
                line_starts.push(index + 1);
            }
        }
        Self {
            source,
            line_starts,
        }
    }

    fn line_with_start(&self, line: usize) -> Option<(usize, &'a str)> {
        let index = line.max(1).saturating_sub(1);
        let start = *self.line_starts.get(index)?;
        let end = self
            .line_starts
            .get(index + 1)
            .copied()
            .unwrap_or(self.source.len());
        self.source.get(start..end).map(|text| (start, text))
    }

    fn line_for_byte(&self, byte: usize) -> usize {
        let byte = byte.min(self.source.len());
        self.line_starts
            .partition_point(|start| *start <= byte)
            .max(1)
    }

    fn byte_column(&self, line: usize, byte: usize) -> usize {
        let line_start = self
            .line_starts
            .get(line.max(1).saturating_sub(1))
            .copied()
            .unwrap_or(0);
        self.source
            .get(line_start..byte.min(self.source.len()))
            .unwrap_or_default()
            .chars()
            .count()
            .saturating_add(1)
    }
}

fn type_hint_entry_for_range(
    program: &ParsedProgram,
    source_index: &TypeHintSourceIndex<'_>,
    expr_id: Option<usize>,
    line: usize,
    start: usize,
    end: usize,
    category: &str,
    ty: &Type,
) -> TypeHintEntry {
    type_hint_entry_for_labels(
        program,
        source_index,
        expr_id,
        line,
        start,
        end,
        category,
        boon_facing_type_compact_label(ty),
        boon_facing_type_detail_label(ty),
        boon_facing_type_display_tree(ty),
    )
}

#[allow(clippy::too_many_arguments)]
fn type_hint_entry_for_labels(
    _program: &ParsedProgram,
    source_index: &TypeHintSourceIndex<'_>,
    expr_id: Option<usize>,
    line: usize,
    start: usize,
    end: usize,
    category: &str,
    compact_label: String,
    detail_label: String,
    display_tree: TypeDisplayNode,
) -> TypeHintEntry {
    TypeHintEntry {
        expr_id,
        line,
        start,
        end,
        anchor_column: source_index.byte_column(line, end),
        category: category.to_owned(),
        compact_label,
        detail_label,
        display_tree,
    }
}

fn collect_call_argument_type_hints(
    program: &ParsedProgram,
    source_index: &TypeHintSourceIndex<'_>,
    expr: &AstExpr,
    expr_types: &TypeHintExprIndex<'_>,
    entries: &mut Vec<TypeHintEntry>,
) {
    let args = match &expr.kind {
        AstExprKind::Call { args, .. } | AstExprKind::Pipe { args, .. } => args,
        _ => return,
    };
    for arg in args {
        let Some((line, start, end)) = call_arg_name_range(source_index, arg) else {
            continue;
        };
        let Some(ty) = expr_types.get(&arg.value) else {
            continue;
        };
        entries.push(type_hint_entry_for_range(
            program,
            source_index,
            Some(arg.value),
            line,
            start,
            end,
            "call_arg",
            ty,
        ));
    }
}

fn expr_kind_gets_type_hint(kind: &AstExprKind) -> bool {
    !matches!(
        kind,
        AstExprKind::StringLiteral(_)
            | AstExprKind::TextLiteral(_)
            | AstExprKind::Number(_)
            | AstExprKind::Delimiter
            | AstExprKind::Unknown(_)
            | AstExprKind::Source
            | AstExprKind::Latest { .. }
            | AstExprKind::ListLiteral { .. }
    )
}

fn type_hint_category_for_expr(kind: &AstExprKind) -> &'static str {
    match kind {
        AstExprKind::Call { .. } | AstExprKind::Pipe { .. } => "call",
        AstExprKind::Path(_) => "path",
        AstExprKind::MatchArm { .. } => "match_arm",
        AstExprKind::Identifier(_) => "expression",
        AstExprKind::Object(_) | AstExprKind::TaggedObject { .. } => "expression",
        _ => "expression",
    }
}

fn collect_statement_type_hints(
    program: &ParsedProgram,
    source_index: &TypeHintSourceIndex<'_>,
    statements: &[AstStatement],
    expr_types: &TypeHintExprIndex<'_>,
    metadata: &TypeHintMetadataIndex<'_>,
    name_bindings: &BTreeMap<String, Type>,
    statement_hint_types: &mut BTreeMap<usize, Type>,
    entries: &mut Vec<TypeHintEntry>,
) {
    for statement in statements {
        match &statement.kind {
            AstStatementKind::Field { .. } | AstStatementKind::Hold { .. } => {
                let value_expr = direct_statement_value_expr_id(statement, &program.expressions);
                let ty = statement_hint_type(
                    program,
                    statement,
                    expr_types,
                    metadata,
                    name_bindings,
                    statement_hint_types,
                );
                entries.push(type_hint_entry_for_range(
                    program,
                    source_index,
                    value_expr,
                    statement.line,
                    statement.start,
                    statement.end,
                    "definition",
                    &ty,
                ));
            }
            AstStatementKind::List { .. } => {
                let ty = statement_field(statement)
                    .and_then(|field| name_bindings.get(field).cloned())
                    .unwrap_or_else(|| simple_list_statement_type(statement, &program.expressions));
                entries.push(type_hint_entry_for_range(
                    program,
                    source_index,
                    statement.expr,
                    statement.line,
                    statement.start,
                    statement.end,
                    "definition",
                    &ty,
                ));
            }
            AstStatementKind::Source { .. } => {
                let source_path = metadata
                    .source_payload_type(statement.id)
                    .unwrap_or_else(exact_empty_object_type);
                entries.push(type_hint_entry_for_range(
                    program,
                    source_index,
                    statement.expr,
                    statement.line,
                    statement.start,
                    statement.end,
                    "source_payload",
                    &source_path,
                ));
            }
            AstStatementKind::Function { name, parameters } => {
                if let Some(function) = metadata.functions.get(name.as_str()).copied() {
                    if let Some((start, end)) = function_name_range(source_index, statement, name) {
                        if let Some(compact_label) = function_signature_compact_label(function) {
                            entries.push(type_hint_entry_for_labels(
                                program,
                                source_index,
                                statement.expr,
                                statement.line,
                                start,
                                end,
                                "function_signature",
                                compact_label,
                                function_signature_detail_label(function),
                                function_signature_display_tree(function),
                            ));
                        }
                        entries.push(type_hint_entry_for_range(
                            program,
                            source_index,
                            statement.expr,
                            statement.line,
                            start,
                            end,
                            "function_return",
                            &function.result.ty,
                        ));
                    }
                    let arg_ranges = function_arg_ranges(parameters);
                    for (index, parameter) in function.parameters.iter().enumerate() {
                        if let Some(Some((start, end))) = arg_ranges.get(index) {
                            entries.push(type_hint_entry_for_range(
                                program,
                                source_index,
                                statement.expr,
                                statement.line,
                                *start,
                                *end,
                                "function_arg",
                                &parameter.flow_type.ty,
                            ));
                        }
                    }
                }
            }
            AstStatementKind::Block | AstStatementKind::Spread | AstStatementKind::Expression => {}
        }
        collect_statement_type_hints(
            program,
            source_index,
            &statement.children,
            expr_types,
            metadata,
            name_bindings,
            statement_hint_types,
            entries,
        );
    }
}

fn statement_hint_type(
    program: &ParsedProgram,
    statement: &AstStatement,
    expr_types: &TypeHintExprIndex<'_>,
    metadata: &TypeHintMetadataIndex<'_>,
    name_bindings: &BTreeMap<String, Type>,
    cache: &mut BTreeMap<usize, Type>,
) -> Type {
    if let Some(ty) = cache.get(&statement.id) {
        return ty.clone();
    }
    let value_expr = direct_statement_value_expr_id(statement, &program.expressions);
    if !statement.children.is_empty() {
        let mut fields = BTreeMap::new();
        let mut field_order = Vec::new();
        for child in &statement.children {
            let Some(field) = statement_output_name(child) else {
                continue;
            };
            let ty = match &child.kind {
                AstStatementKind::Source { .. } => metadata.source_statement_value_type(child),
                _ => {
                    statement_hint_type(program, child, expr_types, metadata, name_bindings, cache)
                }
            };
            insert_ordered_shape_field(&mut fields, &mut field_order, field, ty);
        }
        if !fields.is_empty() {
            let ty = Type::object(ObjectShape {
                fields,
                field_order,
                open: false,
            });
            cache.insert(statement.id, ty.clone());
            return ty;
        }
    }
    let ty = if let Some(ty) = value_expr
        .and_then(|expr_id| expr_types.get(&expr_id).cloned())
        .filter(is_specific_type)
        .or_else(|| statement_pipeline_hint_type(program, statement, expr_types, name_bindings))
        .or_else(|| best_statement_expr_type(statement, expr_types))
    {
        ty
    } else {
        statement_field(statement)
            .and_then(|field| name_bindings.get(field).cloned())
            .or_else(|| value_expr.and_then(|expr_id| expr_types.get(&expr_id).cloned()))
            .unwrap_or_else(|| {
                Type::object(object_shape_for_statement(statement, &program.expressions))
            })
    };
    cache.insert(statement.id, ty.clone());
    ty
}

fn checked_source_expression_flow_types(
    statements: &[AstStatement],
    expressions: &[AstExpr],
    source_payload_shape_table: &[SourcePayloadSyntaxShapeEntry],
) -> Vec<(usize, FlowType)> {
    fn collect(
        statements: &[AstStatement],
        expressions: &[AstExpr],
        source_payload_shape_table: &[SourcePayloadSyntaxShapeEntry],
        result: &mut BTreeMap<usize, FlowType>,
    ) {
        for statement in statements {
            if matches!(statement.kind, AstStatementKind::Source { .. })
                && let Some(payload_type) =
                    source_payload_type_for_statement(statement, source_payload_shape_table)
            {
                let mut owned_expressions = BTreeSet::new();
                if let Some(expression) = statement.expr {
                    collect_expression_tree_ids(expression, expressions, &mut owned_expressions);
                }
                let mut child_expressions = BTreeSet::new();
                for child in &statement.children {
                    collect_statement_expression_tree_ids(
                        child,
                        expressions,
                        &mut child_expressions,
                    );
                }
                for expression in owned_expressions.difference(&child_expressions).copied() {
                    if expressions
                        .get(expression)
                        .is_some_and(|expression| matches!(expression.kind, AstExprKind::Source))
                    {
                        result.insert(
                            expression,
                            FlowType {
                                mode: FlowMode::PresentOrAbsent,
                                ty: payload_type.clone(),
                            },
                        );
                    }
                }
            }
            collect(
                &statement.children,
                expressions,
                source_payload_shape_table,
                result,
            );
        }
    }

    let mut result = BTreeMap::new();
    collect(
        statements,
        expressions,
        source_payload_shape_table,
        &mut result,
    );
    result.into_iter().collect()
}

fn source_payload_type_for_statement(
    statement: &AstStatement,
    source_payload_shape_table: &[SourcePayloadSyntaxShapeEntry],
) -> Option<Type> {
    source_payload_shape_table
        .iter()
        .find(|entry| entry.statement == statement.id)
        .map(|entry| entry.payload_type.clone())
}

fn source_statement_value_type(
    statement: &AstStatement,
    source_payload_shape_table: &[SourcePayloadSyntaxShapeEntry],
) -> Type {
    let payload = source_payload_type_for_statement(statement, source_payload_shape_table)
        .unwrap_or_else(exact_empty_object_type);
    match &statement.kind {
        AstStatementKind::Source {
            event: Some(event), ..
        } => Type::object(ObjectShape::from_ordered_fields(
            [(event.clone(), payload)],
            false,
        )),
        _ => payload,
    }
}

fn is_specific_type(ty: &Type) -> bool {
    match ty {
        Type::Absent | Type::UnresolvedShape { .. } | Type::Unknown | Type::Var(_) => false,
        ty if is_open_object_type(ty) => false,
        Type::List(item) if is_open_object_type(item) => false,
        _ => true,
    }
}

fn best_statement_expr_type(
    statement: &AstStatement,
    expr_types: &TypeHintExprIndex<'_>,
) -> Option<Type> {
    statement_expr_ids(statement)
        .into_iter()
        .rev()
        .filter_map(|expr_id| expr_types.get(&expr_id).cloned())
        .find(is_specific_type)
}

fn statement_pipeline_hint_type(
    program: &ParsedProgram,
    statement: &AstStatement,
    expr_types: &TypeHintExprIndex<'_>,
    name_bindings: &BTreeMap<String, Type>,
) -> Option<Type> {
    let expr_ids = statement_expression_child_expr_ids(statement);
    if !expression_sequence_is_pipeline(&expr_ids, &program.expressions) {
        return None;
    }
    let (first, rest) = expr_ids.split_first()?;
    let mut ty = hint_type_for_expr_id(program, *first, expr_types, name_bindings)?;
    for expr_id in rest {
        if matches!(
            program.expressions.get(*expr_id).map(|expr| &expr.kind),
            Some(AstExprKind::Draining { .. } | AstExprKind::Hold { .. })
        ) {
            continue;
        }
        let Some(AstExpr {
            kind: AstExprKind::Pipe { op, args, .. },
            ..
        }) = program.expressions.get(*expr_id)
        else {
            ty = hint_type_for_expr_id(program, *expr_id, expr_types, name_bindings)?;
            continue;
        };
        ty = match op.as_str() {
            "List/retain"
            | "List/filter"
            | "List/remove"
            | "List/sort_by"
            | "List/then_by"
            | "List/take"
            | "List/move_field_first"
            | "List/move_field_last"
            | "SOURCE" => ty,
            "List/page" => page_result_type(
                list_item_type_from_list_type(&ty).unwrap_or_else(open_object_type),
            ),
            "List/count" | "List/sum" => Type::Number,
            "Text/join" => Type::Text,
            "List/append" => {
                let append_ty = args
                    .iter()
                    .find(|arg| arg.named_name() == Some("item"))
                    .and_then(|arg| {
                        hint_type_for_expr_id(program, arg.value, expr_types, name_bindings)
                    });
                match (ty, append_ty) {
                    (Type::List(item), Some(append_ty)) => {
                        Type::List(Type::shared(widen_structural_type(&item, &append_ty)))
                    }
                    (existing, _) => existing,
                }
            }
            "List/map" => {
                hint_type_for_expr_id(program, *expr_id, expr_types, name_bindings).unwrap_or(ty)
            }
            "Bool/not" | "Bool/and" | "Bool/or" | "Bool/toggle" | "Text/is_not_empty"
            | "List/every" | "List/any" | "List/is_not_empty" => true_false_type(),
            "List/latest" => list_item_type_from_list_type(&ty).unwrap_or_else(open_object_type),
            _ if op.starts_with("Field/") => {
                if let (Type::Object(shape), Some(field)) = (&ty, op.strip_prefix("Field/")) {
                    shape.fields.get(field).cloned().unwrap_or(Type::Unknown)
                } else {
                    Type::Unknown
                }
            }
            _ => hint_type_for_expr_id(program, *expr_id, expr_types, name_bindings).unwrap_or(ty),
        };
    }
    Some(ty)
}

fn statement_expression_child_expr_ids(statement: &AstStatement) -> Vec<usize> {
    statement
        .children
        .iter()
        .filter_map(|child| {
            matches!(
                child.kind,
                AstStatementKind::Expression
                    | AstStatementKind::Spread
                    | AstStatementKind::Hold { .. }
                    | AstStatementKind::List { field: None, .. }
            )
            .then(|| child.expr.or_else(|| first_child_expr_id(child)))
            .flatten()
        })
        .collect()
}

fn hint_type_for_expr_id(
    program: &ParsedProgram,
    expr_id: usize,
    expr_types: &TypeHintExprIndex<'_>,
    name_bindings: &BTreeMap<String, Type>,
) -> Option<Type> {
    expr_types
        .get(&expr_id)
        .filter(|ty| is_specific_type(ty))
        .cloned()
        .or_else(|| match &program.expressions.get(expr_id)?.kind {
            AstExprKind::Identifier(name) => name_bindings.get(name).cloned(),
            AstExprKind::Path(parts) => type_from_longest_binding_prefix(name_bindings, parts),
            _ => None,
        })
}

fn function_signature_compact_label(function: &FunctionTypeEntry) -> Option<String> {
    let result_label = signature_type_compact_label(&function.result.ty);
    let arg_labels = function
        .parameters
        .iter()
        .map(|parameter| {
            format!(
                "{}: {}",
                parameter.name,
                signature_type_compact_label(&parameter.flow_type.ty)
            )
        })
        .collect::<Vec<_>>();
    if arg_labels.is_empty() {
        return None;
    }
    let label = format!("({}) -> {result_label}", arg_labels.join(", "));
    Some(label)
}

fn function_signature_detail_label(function: &FunctionTypeEntry) -> String {
    let args = function
        .parameters
        .iter()
        .map(|parameter| {
            format!(
                "{}: {}",
                parameter.name,
                boon_facing_type_detail_label(&parameter.flow_type.ty)
            )
        })
        .collect::<Vec<_>>()
        .join(", ");
    format!(
        "function {}({args}) -> {}",
        function.name,
        boon_facing_type_detail_label(&function.result.ty)
    )
}

fn function_signature_display_tree(function: &FunctionTypeEntry) -> TypeDisplayNode {
    TypeDisplayNode::Function {
        name: Some(function.name.clone()),
        args: function
            .parameters
            .iter()
            .map(|parameter| TypeDisplayFunctionArg {
                name: Some(parameter.name.clone()),
                ty: boon_facing_type_display_tree(&parameter.flow_type.ty),
            })
            .collect(),
        result: Box::new(boon_facing_type_display_tree(&function.result.ty)),
    }
}

fn signature_type_compact_label(ty: &Type) -> String {
    match ty {
        Type::Object(shape) if shape.fields.is_empty() && !shape.open => "[]".to_owned(),
        Type::Object(shape) if shape.fields.is_empty() => "[...]".to_owned(),
        Type::Object(_) => {
            let label = boon_facing_type_compact_label(ty);
            if label.chars().count() <= 28 && !label.contains("...") {
                label
            } else {
                "[...]".to_owned()
            }
        }
        Type::Unknown | Type::Var(_) | Type::UnresolvedShape { .. } => "VALUE".to_owned(),
        _ => {
            let label = boon_facing_type_compact_label(ty);
            if label == "VALUE" {
                "VALUE".to_owned()
            } else {
                label
            }
        }
    }
}

fn function_name_range(
    source_index: &TypeHintSourceIndex<'_>,
    statement: &AstStatement,
    name: &str,
) -> Option<(usize, usize)> {
    let (line_start, line_text) = source_index.line_with_start(statement.line)?;
    let keyword = line_text.find("FUNCTION")?;
    let name_search_start = keyword + "FUNCTION".len();
    let name_offset = line_text.get(name_search_start..)?.find(name)?;
    let start = line_start + name_search_start + name_offset;
    Some((start, start + name.len()))
}

fn function_arg_ranges(parameters: &[AstParameter]) -> Vec<Option<(usize, usize)>> {
    parameters
        .iter()
        .map(|parameter| Some((parameter.start, parameter.end)))
        .collect()
}

fn call_arg_name_range(
    source_index: &TypeHintSourceIndex<'_>,
    arg: &AstCallArg,
) -> Option<(usize, usize, usize)> {
    let name = arg.named_name()?;
    let line = source_index.line_for_byte(arg.start);
    let (line_start, line_text) = source_index.line_with_start(line)?;
    let search_start = arg.start.saturating_sub(line_start).min(line_text.len());
    let search_end = arg.end.saturating_sub(line_start).min(line_text.len());
    let range_text = line_text.get(search_start..search_end)?;
    let name_offset = range_text.find(name)?;
    let start = line_start + search_start + name_offset;
    Some((line, start, start + name.len()))
}

fn line_for_byte(source: &str, byte: usize) -> usize {
    let mut line = 1;
    let mut offset = 0;
    for chunk in source.split_inclusive('\n') {
        offset += chunk.len();
        if byte < offset {
            return line;
        }
        line += 1;
    }
    line
}

fn collect_payload_pattern_fields(
    statements: &[AstStatement],
    expressions: &[AstExpr],
    source_lookup: &SourcePayloadPathLookup,
    fields_by_source: &mut BTreeMap<String, BTreeMap<String, Type>>,
) {
    for statement in statements {
        if let Some(expr_id) = statement.expr
            && let Some(AstExpr {
                kind: AstExprKind::When { input, .. },
                ..
            }) = expressions.get(expr_id)
        {
            for source_path in expr_source_paths(*input, expressions, source_lookup) {
                if let Some(fields) = fields_by_source.get_mut(&source_path) {
                    if let Some(field) =
                        expr_source_payload_field(*input, expressions, source_lookup)
                        && let Some(selector) =
                            source_payload_tag_selector_type(&statement.children, expressions)
                        && !source_payload_field_has_intrinsic_type(&field)
                    {
                        // A closed tag match is structural evidence for an
                        // arbitrary payload field's exact variant set. It must
                        // not replace renderer-defined event fields such as
                        // `key` and `text`.
                        fields.insert(field, selector);
                    }
                    for child in &statement.children {
                        if let Some(AstExpr {
                            kind: AstExprKind::MatchArm { pattern, .. },
                            ..
                        }) = child.expr.and_then(|expr_id| expressions.get(expr_id))
                        {
                            for field in source_payload_fields_from_pattern(pattern) {
                                fields.insert(field.to_owned(), source_payload_field_type(&field));
                            }
                        }
                    }
                }
            }
        }
        collect_payload_pattern_fields(
            &statement.children,
            expressions,
            source_lookup,
            fields_by_source,
        );
    }
}

fn source_payload_field_has_intrinsic_type(field: &str) -> bool {
    matches!(
        field,
        "press"
            | "click"
            | "double_click"
            | "blur"
            | "change"
            | "key_down"
            | "bytes"
            | "key"
            | "text"
    )
}

fn expr_source_payload_field(
    expression: usize,
    expressions: &[AstExpr],
    source_lookup: &SourcePayloadPathLookup,
) -> Option<String> {
    match &expressions.get(expression)?.kind {
        AstExprKind::Path(parts) => match source_lookup.access_for_parts(parts)? {
            SourcePayloadAccess::Field(field) => Some(field),
            SourcePayloadAccess::Direct(_) | SourcePayloadAccess::UnknownField(_) => None,
        },
        _ => None,
    }
}

fn source_payload_tag_selector_type(
    arms: &[AstStatement],
    expressions: &[AstExpr],
) -> Option<Type> {
    let mut variants = Vec::new();
    for pattern in arms.iter().filter_map(|arm| {
        arm.expr
            .and_then(|expression| expressions.get(expression))
            .and_then(|expression| match &expression.kind {
                AstExprKind::MatchArm { pattern, .. } => Some(pattern),
                _ => None,
            })
    }) {
        match pattern {
            AstMatchPattern::Tag { name, fields } => {
                variants.push(if fields.is_empty() {
                    Variant::Tag(name.clone())
                } else {
                    Variant::Tagged {
                        tag: name.clone(),
                        fields: ObjectShape {
                            fields: fields
                                .iter()
                                .map(|field| (field.clone(), Type::Unknown))
                                .collect(),
                            field_order: fields.clone(),
                            open: false,
                        }
                        .into(),
                    }
                });
            }
            AstMatchPattern::Wildcard | AstMatchPattern::Binding { .. } => {}
            AstMatchPattern::Number { .. }
            | AstMatchPattern::Text { .. }
            | AstMatchPattern::Bits { .. } => return None,
            AstMatchPattern::Invalid { .. } => {
                unreachable!("invalid match patterns are rejected by boon_parser")
            }
        }
    }
    variants.sort_by(|left, right| {
        let left = match left {
            Variant::Tag(tag) | Variant::Tagged { tag, .. } => tag,
        };
        let right = match right {
            Variant::Tag(tag) | Variant::Tagged { tag, .. } => tag,
        };
        left.cmp(right)
    });
    variants.dedup();
    (!variants.is_empty()).then_some(Type::VariantSet(variants.into()))
}

fn collect_payload_hold_update_types(
    roots: &[AstStatement],
    statements: &[AstStatement],
    expressions: &[AstExpr],
    source_lookup: &SourcePayloadPathLookup,
    fields_by_source: &mut BTreeMap<String, BTreeMap<String, Type>>,
) {
    for statement in statements {
        if let Some(expr_id) = statement.expr
            && let Some(AstExpr {
                kind: AstExprKind::Hold { initial, .. },
                ..
            }) = expressions.get(expr_id)
        {
            let initial = pipeline_source_expr_id(roots, expr_id, *initial, expressions);
            let expected = expressions
                .get(initial)
                .map(|expression| simple_expr_type(expression, expressions))
                .map(|ty| {
                    if type_accepts_true_false(&ty) {
                        true_false_type()
                    } else {
                        ty
                    }
                });
            if let Some(expected) = expected
                .filter(is_specific_type)
                .filter(|ty| !matches!(ty, Type::RenderContract))
            {
                for update in hold_update_exprs(statement, expressions) {
                    let Some(AstExpr {
                        kind: AstExprKind::Path(parts),
                        ..
                    }) = expressions.get(update)
                    else {
                        continue;
                    };
                    let Some(SourcePayloadAccess::Field(field)) =
                        source_lookup.access_for_parts(parts)
                    else {
                        continue;
                    };
                    for source_path in source_lookup.source_paths_for_parts(parts) {
                        if let Some(fields) = fields_by_source.get_mut(&source_path) {
                            fields.insert(field.clone(), expected.clone());
                        }
                    }
                }
            }
        }
        collect_payload_hold_update_types(
            roots,
            &statement.children,
            expressions,
            source_lookup,
            fields_by_source,
        );
    }
}

struct SourcePayloadPathLookup {
    exact_prefix: BTreeMap<String, Vec<String>>,
    suffix: BTreeMap<String, Vec<String>>,
    source_order: BTreeMap<String, usize>,
}

impl SourcePayloadPathLookup {
    fn new(source_paths: &BTreeSet<String>) -> Self {
        let mut exact_prefix = BTreeMap::<String, Vec<String>>::new();
        let mut suffix = BTreeMap::<String, Vec<String>>::new();
        let mut source_order = BTreeMap::new();
        for (index, source_path) in source_paths.iter().enumerate() {
            source_order.insert(source_path.clone(), index);
            for alias in source_path_aliases(source_path) {
                push_unique(
                    exact_prefix.entry(alias.clone()).or_default(),
                    source_path.clone(),
                );
                let parts = alias.split('.').collect::<Vec<_>>();
                for index in 0..parts.len() {
                    push_unique(
                        suffix.entry(parts[index..].join(".")).or_default(),
                        source_path.clone(),
                    );
                }
            }
        }
        Self {
            exact_prefix,
            suffix,
            source_order,
        }
    }

    fn access_for_parts(&self, parts: &[String]) -> Option<SourcePayloadAccess> {
        source_path_part_candidates(parts)
            .into_iter()
            .find_map(|parts| self.access_for_normalized_parts(&parts))
    }

    fn access_for_normalized_parts(
        &self,
        normalized_parts: &[String],
    ) -> Option<SourcePayloadAccess> {
        let path = normalized_parts.join(".");
        if path.is_empty() {
            return None;
        }

        let mut best = SourcePayloadAccessMatch::default();
        if let Some(sources) = self.suffix.get(&path) {
            for source_path in sources {
                best.push(self.source_index(source_path), || {
                    SourcePayloadAccess::Direct(source_path.clone())
                });
            }
        }

        let path_parts = path.split('.').collect::<Vec<_>>();
        for end in 1..path_parts.len() {
            let prefix = path_parts[..end].join(".");
            let suffix = path_parts[end..].join(".");
            if let Some(sources) = self.exact_prefix.get(&prefix) {
                for source_path in sources {
                    best.push(self.source_index(source_path), || {
                        source_payload_access_for_suffix(&suffix)
                    });
                }
            }
        }

        if let Some((field, base_without_field)) = normalized_parts.split_last() {
            let base_without_field = base_without_field.join(".");
            if !base_without_field.is_empty()
                && let Some(sources) = self.suffix.get(&base_without_field)
            {
                for source_path in sources {
                    best.push(self.source_index(source_path), || {
                        source_payload_access_for_suffix(field)
                    });
                }
            }
        }

        best.access
    }

    fn source_paths_for_parts(&self, parts: &[String]) -> Vec<String> {
        for normalized_parts in source_path_part_candidates(parts) {
            let matches = self.source_paths_for_normalized_parts(&normalized_parts);
            if !matches.is_empty() {
                return matches;
            }
        }
        Vec::new()
    }

    fn source_paths_for_normalized_parts(&self, normalized_parts: &[String]) -> Vec<String> {
        let path = normalized_parts.join(".");
        let path_without_payload = parts_without_payload(normalized_parts).join(".");
        let mut matches = Vec::new();
        let path_parts = path.split('.').collect::<Vec<_>>();
        for end in 1..=path_parts.len() {
            if let Some(sources) = self.exact_prefix.get(&path_parts[..end].join(".")) {
                for source in sources {
                    push_unique(&mut matches, source.clone());
                }
            }
        }
        for start in 0..path_parts.len() {
            if let Some(sources) = self.suffix.get(&path_parts[start..].join(".")) {
                for source in sources {
                    push_unique(&mut matches, source.clone());
                }
                break;
            }
        }
        if let Some(sources) = self.suffix.get(&path_without_payload) {
            for source in sources {
                push_unique(&mut matches, source.clone());
            }
        }
        matches
    }

    fn source_index(&self, source_path: &str) -> usize {
        self.source_order
            .get(source_path)
            .copied()
            .unwrap_or(usize::MAX)
    }
}

#[derive(Default)]
struct SourcePayloadAccessMatch {
    index: Option<usize>,
    access: Option<SourcePayloadAccess>,
}

impl SourcePayloadAccessMatch {
    fn push(&mut self, source_index: usize, access: impl FnOnce() -> SourcePayloadAccess) {
        if self.index.is_none_or(|index| source_index < index) {
            self.index = Some(source_index);
            self.access = Some(access());
        }
    }
}

fn source_path_aliases(source_path: &str) -> Vec<String> {
    let mut aliases = vec![source_path.to_owned()];
    aliases.push(
        source_path
            .strip_prefix("store.")
            .unwrap_or(source_path)
            .to_owned(),
    );
    if let Some((_, relative)) = source_path.split_once('.') {
        aliases.push(relative.to_owned());
    }
    let mut unique = Vec::new();
    for alias in aliases {
        push_unique(&mut unique, alias);
    }
    unique
}

fn push_unique<T: Eq>(items: &mut Vec<T>, item: T) {
    if !items.iter().any(|existing| existing == &item) {
        items.push(item);
    }
}

fn expr_source_paths(
    expr_id: usize,
    expressions: &[AstExpr],
    source_lookup: &SourcePayloadPathLookup,
) -> Vec<String> {
    match expressions.get(expr_id).map(|expr| &expr.kind) {
        Some(AstExprKind::Identifier(value)) => {
            source_lookup.source_paths_for_parts(std::slice::from_ref(value))
        }
        Some(AstExprKind::Path(parts)) => source_lookup.source_paths_for_parts(parts),
        Some(AstExprKind::Pipe { input, .. }) | Some(AstExprKind::When { input, .. }) => {
            expr_source_paths(*input, expressions, source_lookup)
        }
        _ => Vec::new(),
    }
}

fn parts_without_payload(parts: &[String]) -> &[String] {
    match parts.last().map(String::as_str) {
        Some("press" | "click" | "double_click" | "blur" | "change" | "key_down") => {
            &parts[..parts.len().saturating_sub(1)]
        }
        Some(_) => &parts[..parts.len().saturating_sub(1)],
        _ => parts,
    }
}

fn source_payload_fields_from_pattern(pattern: &AstMatchPattern) -> Vec<String> {
    match pattern {
        AstMatchPattern::Tag { fields, .. } => fields.clone(),
        _ => Vec::new(),
    }
}

fn path_is_event_payload_parts(parts: &[String]) -> bool {
    parts.windows(2).any(|window| {
        window[0] == "event"
            && matches!(
                window[1].as_str(),
                "press" | "click" | "double_click" | "blur" | "change" | "key_down"
            )
    })
}

fn scoped_path(scope: &[String], name: &str) -> String {
    if scope.is_empty() {
        name.to_owned()
    } else {
        format!("{}.{name}", scope.join("."))
    }
}

fn true_false_type() -> Type {
    Type::VariantSet(
        vec![
            Variant::Tag("False".to_owned()),
            Variant::Tag("True".to_owned()),
        ]
        .into(),
    )
}

fn order_direction_type() -> Type {
    tag_union_type(&["Ascending", "Descending"])
}

fn page_position_type() -> Type {
    Type::VariantSet(
        vec![
            Variant::Tag("Start".to_owned()),
            Variant::Tagged {
                tag: "Cursor".to_owned(),
                fields: ObjectShape::from_ordered_fields(
                    [("value".to_owned(), Type::Bytes(BytesType::Dynamic))],
                    false,
                ),
            },
        ]
        .into(),
    )
}

fn page_result_type(item: Type) -> Type {
    let next = Type::VariantSet(
        vec![
            Variant::Tag("End".to_owned()),
            Variant::Tagged {
                tag: "Cursor".to_owned(),
                fields: ObjectShape::from_ordered_fields(
                    [("value".to_owned(), Type::Bytes(BytesType::Dynamic))],
                    false,
                ),
            },
        ]
        .into(),
    );
    Type::VariantSet(
        vec![
            Variant::Tagged {
                tag: "Page".to_owned(),
                fields: ObjectShape::from_ordered_fields(
                    [
                        ("items".to_owned(), Type::List(Type::shared(item))),
                        ("next".to_owned(), next),
                    ],
                    false,
                ),
            },
            Variant::Tag("PageExpired".to_owned()),
            Variant::Tag("InvalidPageCursor".to_owned()),
            Variant::Tag("InvalidPageSize".to_owned()),
            Variant::Tag("PageWorkLimitExceeded".to_owned()),
        ]
        .into(),
    )
}

fn session_info_intrinsic_type(function: &str) -> Option<Type> {
    match function {
        "SessionInfo/status" => Some(Type::VariantSet(
            vec![
                Variant::Tag("Connecting".to_owned()),
                Variant::Tag("Current".to_owned()),
                Variant::Tag("Stale".to_owned()),
                Variant::Tagged {
                    tag: "Failed".to_owned(),
                    fields: ObjectShape::from_ordered_fields(
                        [("code".to_owned(), Type::Text)],
                        false,
                    ),
                },
            ]
            .into(),
        )),
        "SessionInfo/principal" => Some(Type::VariantSet(
            vec![
                Variant::Tag("Anonymous".to_owned()),
                Variant::Tagged {
                    tag: "Authenticated".to_owned(),
                    fields: ObjectShape::from_ordered_fields(
                        [
                            ("subject".to_owned(), Type::Text),
                            ("roles".to_owned(), Type::List(Type::shared(Type::Text))),
                        ],
                        false,
                    ),
                },
            ]
            .into(),
        )),
        _ => None,
    }
}

fn session_info_intrinsic_allowed(function: &str, role: ProgramRole) -> bool {
    match function {
        "SessionInfo/status" => matches!(
            role,
            ProgramRole::Client | ProgramRole::Session | ProgramRole::Server
        ),
        "SessionInfo/principal" => matches!(role, ProgramRole::Session | ProgramRole::Server),
        _ => false,
    }
}

fn session_info_role_diagnostic(function: &str, role: ProgramRole) -> String {
    match (function, role) {
        ("SessionInfo/principal", ProgramRole::Client) => {
            "`SessionInfo/principal()` is unavailable in Client; expose only explicitly selected account-facing data from Session".to_owned()
        }
        _ => format!("`{function}()` is unavailable in {}", role.namespace()),
    }
}

fn tag_type(tag: &str) -> Type {
    Type::VariantSet(vec![Variant::Tag(tag.to_owned())].into())
}

fn tag_union_type(tags: &[&str]) -> Type {
    Type::VariantSet(
        tags.iter()
            .map(|tag| Variant::Tag((*tag).to_owned()))
            .collect(),
    )
}

fn rounding_rule_type() -> Type {
    tag_union_type(&ExactRoundingRule::ALL.map(ExactRoundingRule::as_tag))
}

fn stripe_kind_type(direction: Option<&Type>) -> Type {
    let Some(Type::VariantSet(variants)) = direction else {
        return tag_union_type(&["Row", "Stack"]);
    };
    let mut tags = BTreeSet::new();
    for variant in variants {
        match variant {
            Variant::Tag(tag) if tag == "Row" => {
                tags.insert("Row");
            }
            Variant::Tag(tag) if tag == "Column" => {
                tags.insert("Stack");
            }
            _ => {
                tags.insert("Row");
                tags.insert("Stack");
            }
        }
    }
    if tags.is_empty() {
        tags.insert("Row");
        tags.insert("Stack");
    }
    tag_union_type(&tags.into_iter().collect::<Vec<_>>())
}

fn render_slot_type_error(slot_name: &str, actual_type: &Type) -> String {
    let expected = match slot_name {
        "items" | "children" => "LIST<[...]>",
        _ => "[...]",
    };
    format!(
        "`{slot_name}` expects objects accepted by `document:`\nexpected: {expected}\nfound: {}",
        boon_facing_type_label(actual_type)
    )
}

fn is_document_render_object_type(ty: &Type) -> bool {
    RenderContractRegistry::default().is_any_renderable_object_type(ty)
}

fn is_no_element_type(ty: &Type) -> bool {
    matches!(
        ty,
        Type::VariantSet(variants)
            if variants.iter().all(|variant| {
                matches!(variant, Variant::Tag(tag) if tag == "NoElement")
            })
    )
}

fn type_contains_renderable(ty: &Type) -> bool {
    match ty {
        Type::RenderContract => true,
        ty if is_document_render_object_type(ty) => true,
        ty if is_no_element_type(ty) => true,
        Type::List(item) => type_contains_renderable(item),
        Type::Map { key, value } => {
            type_contains_renderable(key) || type_contains_renderable(value)
        }
        Type::Set(item) => type_contains_renderable(item),
        Type::Object(shape) => shape.fields.values().any(type_contains_renderable),
        Type::VariantSet(variants) => variants.iter().any(|variant| match variant {
            Variant::Tag(_) => false,
            Variant::Tagged { fields, .. } => fields.fields.values().any(type_contains_renderable),
        }),
        Type::Union(members) => members.iter().any(type_contains_renderable),
        Type::Function { result, .. } => type_contains_renderable(&result.ty),
        Type::Text
        | Type::Number
        | Type::Bytes(_)
        | Type::Bits { .. }
        | Type::Absent
        | Type::Var(_)
        | Type::Unknown
        | Type::UnresolvedShape { .. } => false,
    }
}

fn type_contains_no_element(ty: &Type) -> bool {
    match ty {
        ty if is_no_element_type(ty) => true,
        Type::List(item) => type_contains_no_element(item),
        Type::Map { key, value } => {
            type_contains_no_element(key) || type_contains_no_element(value)
        }
        Type::Set(item) => type_contains_no_element(item),
        Type::Object(shape) => shape.fields.values().any(type_contains_no_element),
        Type::VariantSet(variants) => variants.iter().any(|variant| match variant {
            Variant::Tag(_) => false,
            Variant::Tagged { fields, .. } => fields.fields.values().any(type_contains_no_element),
        }),
        Type::Union(members) => members.iter().any(type_contains_no_element),
        Type::Function { result, .. } => type_contains_no_element(&result.ty),
        Type::Text
        | Type::Number
        | Type::Bytes(_)
        | Type::Bits { .. }
        | Type::Absent
        | Type::RenderContract
        | Type::Var(_)
        | Type::Unknown
        | Type::UnresolvedShape { .. } => false,
    }
}

fn type_contains_absence(ty: &Type) -> bool {
    match ty {
        Type::Absent => true,
        Type::List(item) => type_contains_absence(item),
        Type::Map { key, value } => type_contains_absence(key) || type_contains_absence(value),
        Type::Set(item) => type_contains_absence(item),
        Type::Object(shape) => shape.fields.values().any(type_contains_absence),
        Type::VariantSet(variants) => variants.iter().any(|variant| match variant {
            Variant::Tag(_) => false,
            Variant::Tagged { fields, .. } => fields.fields.values().any(type_contains_absence),
        }),
        Type::Union(members) => members.iter().any(type_contains_absence),
        Type::Function { result, .. } => type_contains_absence(&result.ty),
        Type::Text
        | Type::Number
        | Type::Bytes(_)
        | Type::Bits { .. }
        | Type::RenderContract
        | Type::Var(_)
        | Type::Unknown
        | Type::UnresolvedShape { .. } => false,
    }
}

fn expr_is_skip(expr: &AstExpr) -> bool {
    matches!(&expr.kind, AstExprKind::Tag(tag) if tag == "SKIP")
}

fn open_object_type() -> Type {
    Type::object(ObjectShape::new(BTreeMap::new(), true))
}

fn embedded_program_source_units_type() -> Type {
    Type::List(Type::shared(Type::object(
        ObjectShape::from_ordered_fields(
            [
                ("path".to_owned(), Type::Text),
                ("source".to_owned(), Type::Text),
            ],
            false,
        ),
    )))
}

fn exact_empty_object_type() -> Type {
    Type::object(ObjectShape::new(BTreeMap::new(), false))
}

fn unresolved_shape(reason: impl Into<String>) -> Type {
    Type::UnresolvedShape {
        reason: reason.into(),
    }
}

fn is_open_object_type(ty: &Type) -> bool {
    matches!(ty, Type::Object(shape) if shape.open && shape.fields.is_empty())
}

fn collect_type_vars(ty: &Type, vars: &mut BTreeSet<TypeVar>) {
    match ty {
        Type::Var(var) => {
            vars.insert(*var);
        }
        Type::List(item) => collect_type_vars(item, vars),
        Type::Map { key, value } => {
            collect_type_vars(key, vars);
            collect_type_vars(value, vars);
        }
        Type::Set(item) => collect_type_vars(item, vars),
        Type::Function { args, result } => {
            for arg in args {
                collect_type_vars(arg, vars);
            }
            collect_type_vars(&result.ty, vars);
        }
        Type::Object(shape) => {
            for field in shape.fields.values() {
                collect_type_vars(field, vars);
            }
        }
        Type::VariantSet(variants) => {
            for variant in variants {
                if let Variant::Tagged { fields, .. } = variant {
                    for field in fields.fields.values() {
                        collect_type_vars(field, vars);
                    }
                }
            }
        }
        Type::Union(members) => {
            for member in members {
                collect_type_vars(member, vars);
            }
        }
        Type::Text
        | Type::Number
        | Type::Bytes(_)
        | Type::Bits { .. }
        | Type::Absent
        | Type::RenderContract
        | Type::Unknown
        | Type::UnresolvedShape { .. } => {}
    }
}

fn builtin_signature_coverage(program: &ParsedProgram) -> Vec<String> {
    let mut names = program.operators.clone();
    names.extend(program.functions.iter().cloned());
    names.sort();
    names.dedup();
    names
}

#[allow(dead_code)]
fn object_shape(fields: &[AstRecordField]) -> ObjectShape {
    ObjectShape::from_ordered_fields(
        fields
            .iter()
            .map(|field| (field.name.clone(), open_object_type())),
        false,
    )
}

